// Erzeugt von scripts/build-data.mjs – nicht von Hand bearbeiten (Quelle: data/src).
window.MEDI_DETAILS = Object.assign(window.MEDI_DETAILS || {}, {"famciclovir":{"wirkmechanismus":"Hemmt die Vermehrung von Herpesviren in befallenen Zellen. Famciclovir ist ein Prodrug, das nach der Aufnahme im Darm und in der Leber (u. a. durch Aldehydoxidase) rasch in den Wirkstoff Penciclovir umgewandelt wird. In virusinfizierten Zellen wird Penciclovir durch die virale Thymidinkinase zu Penciclovirtriphosphat aktiviert, das die virale DNA-Polymerase hemmt und lange in der Zelle verbleibt. Latente Viren werden nicht beseitigt.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen"],"haeufig":["Schwindel","Übelkeit, Erbrechen, Bauchschmerzen, Durchfall","Abweichende Leberwerte","Hautausschlag, Juckreiz"],"gelegentlich":["Verwirrtheit und Schläfrigkeit (vor allem bei älteren Menschen)","Thrombozytopenie (Blutplättchenmangel)","Nesselsucht, Angioödem"],"selten":["Halluzinationen","Herzklopfen","Cholestatische Gelbsucht"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Krampfanfälle","Schwere Hautreaktionen (Erythema multiforme, Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Leukozytoklastische Vaskulitis (Gefässentzündung der Haut)"]},"schwangerschaft":"Nur begrenzte Erfahrungen; nur anwenden, wenn der Nutzen das mögliche Risiko überwiegt.","stillzeit":"Im Tierversuch geht Penciclovir in die Milch über; Anwendung nur, wenn der Nutzen das Risiko überwiegt.","hinweise":["Bei Gürtelrose möglichst innerhalb von 72 Stunden nach Auftreten des Ausschlags beginnen.","Kann unabhängig von den Mahlzeiten eingenommen werden.","Schwindel, Schläfrigkeit oder Verwirrtheit können die Fahrtüchtigkeit beeinträchtigen.","Genitalherpes bleibt ansteckend, auch unter Behandlung – Kondome verwenden, bei Beschwerden auf Geschlechtsverkehr verzichten."],"darreichung":["Filmtabletten"]},"famotidin":{"wirkmechanismus":"Vermindert die Bildung von Magensäure. Famotidin blockiert kompetitiv die Histamin-H2-Rezeptoren der säurebildenden Belegzellen der Magenschleimhaut und senkt so die basale sowie die durch Nahrung oder Histamin angeregte Säure- und Pepsinsekretion. Die Wirkung setzt nach etwa einer Stunde ein und hält 10–12 Stunden an. Anders als Cimetidin hemmt Famotidin die Cytochrom-P450-Enzyme praktisch nicht.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Schwindel","Obstipation (Verstopfung)","Durchfall"],"gelegentlich":["Mundtrockenheit","Übelkeit, Erbrechen","Bauchbeschwerden, Blähungen","Appetitlosigkeit","Müdigkeit","Hautausschlag, Juckreiz","Geschmacksstörungen"],"selten":["Überempfindlichkeitsreaktionen wie Anaphylaxie, Angioödem oder Bronchospasmus","Nesselsucht (Urtikaria)","Erhöhte Leberwerte, Gelbsucht durch Gallenstau","Gelenkschmerzen"],"sehrSelten":["Blutbildveränderungen bis zur Agranulozytose oder Panzytopenie","Vorübergehende psychische Störungen wie Verwirrtheit, Halluzinationen, Unruhe, Depression","Krampfanfälle (vor allem bei eingeschränkter Nierenfunktion)","Stevens-Johnson-Syndrom und toxische epidermale Nekrolyse (schwere Hautreaktionen)","QT-Verlängerung, AV-Block","Haarausfall","Impotenz, verminderte Libido"]},"schwangerschaft":"Nur anwenden, wenn eindeutig notwendig und nach ärztlicher Abwägung.","stillzeit":"Famotidin geht in die Muttermilch über – entweder abstillen oder auf die Behandlung verzichten.","hinweise":["Unabhängig von den Mahlzeiten einnehmen; abends eingenommen wirkt es besonders gegen nächtliche Säure.","Bei eingeschränkter Nierenfunktion die Dosis ärztlich anpassen lassen.","Rezeptfreie Tabletten gegen Sodbrennen ohne ärztlichen Rat nicht länger als 2 Wochen einnehmen."],"darreichung":["Filmtabletten"]},"faricimab":{"wirkmechanismus":"Hemmt gleichzeitig zwei Signalwege, die zu undichten, krankhaften Blutgefässen in der Netzhaut führen. Faricimab ist ein humanisierter bispezifischer IgG1-Antikörper, der sowohl VEGF-A als auch Angiopoietin-2 (Ang-2) bindet und neutralisiert. Die Ang-2-Hemmung stabilisiert zusätzlich die Gefässwände und vermindert Entzündung und Gefässdurchlässigkeit. Der Fc-Teil ist so verändert, dass der Antikörper rasch aus dem Blut entfernt wird.","nebenwirkungen":{"haeufig":["Grauer Star (Katarakt)","Bindehautblutung","Glaskörperabhebung, Glaskörpertrübungen (Mouches volantes)","Erhöhter Augeninnendruck","Augenschmerzen","Riss des retinalen Pigmentepithels (bei feuchter Makuladegeneration)"],"gelegentlich":["Endophthalmitis (schwere Infektion im Augeninneren)","Entzündung im Augeninneren (Uveitis, Iritis, Vitritis)","Netzhautriss oder Netzhautablösung","Augenreizung, Juckreiz, Fremdkörpergefühl, vermehrter Tränenfluss","Verschwommenes Sehen, Augenrötung","Hornhautabschürfung, Schmerzen bei der Injektion"],"unbekannt":["Retinale Vaskulitis (Entzündung der Netzhautgefässe), auch mit Gefässverschluss","Linsenverletzung durch die Injektion","Arterielle Thromboembolien (theoretisches Risiko von VEGF-Hemmern)"]},"schwangerschaft":"Nur anwenden, wenn der Nutzen das mögliche Risiko für das Ungeborene überwiegt, da die VEGF-Hemmung die Entwicklung beeinträchtigen kann. Frauen im gebärfähigen Alter verhüten während und mindestens 3 Monate nach der letzten Injektion.","stillzeit":"Stillen wird während der Behandlung nicht empfohlen.","hinweise":["Bei zunehmenden Augenschmerzen, Rötung, Lichtempfindlichkeit oder plötzlicher Sehverschlechterung nach der Injektion sofort die Augenärztin oder den Augenarzt aufsuchen.","Nach der Injektion kann das Sehen vorübergehend gestört sein – bis zur Erholung nicht Auto fahren.","Kontroll- und Injektionstermine einhalten; Behandlungslücken können das Sehvermögen gefährden."],"darreichung":["Injektionslösung zur Injektion in den Glaskörper"]},"febuxostat":{"wirkmechanismus":"Senkt die Harnsäure, indem es deren Bildung im Körper bremst. Febuxostat hemmt selektiv und stark die Xanthinoxidase, die Hypoxanthin und Xanthin zu Harnsäure umwandelt. Anders als Allopurinol ist es kein Purinabkömmling und wird vorwiegend in der Leber abgebaut, weshalb bei leichter bis mässiger Niereninsuffizienz keine Dosisanpassung nötig ist.","nebenwirkungen":{"haeufig":["Gichtanfälle zu Beginn der Behandlung","Kopfschmerzen","Durchfall, Übelkeit","Veränderte Leberwerte","Hautausschlag","Ödeme (Wassereinlagerungen)"],"gelegentlich":["Schwindel, Kribbeln, Schläfrigkeit, Geschmacksstörungen","Vorhofflimmern, Herzklopfen, Bluthochdruck","Erhöhtes TSH, Schilddrüsenunterfunktion","Bauchschmerzen, Sodbrennen, Verstopfung, Erbrechen","Gelenk- und Muskelschmerzen","Nierenversagen, Nierensteine, Blut im Urin","Juckreiz, Nesselsucht","Müdigkeit, Appetitveränderungen, Gewichtszunahme"],"selten":["Anaphylaxie und andere schwere Überempfindlichkeitsreaktionen, Angioödem","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS)","Hepatitis, Gelbsucht, Leberschäden","Blutbildstörungen (Agranulozytose, Thrombozytopenie, Panzytopenie)","Plötzlicher Herztod","Rhabdomyolyse (Muskelzerfall), interstitielle Nephritis"]},"schwangerschaft":"Nicht empfohlen; es liegen nur sehr wenige Erfahrungen vor.","stillzeit":"Nicht anwenden; es ist unbekannt, ob Febuxostat in die Muttermilch übergeht.","hinweise":["In den ersten Monaten treten häufig Gichtanfälle auf – nicht absetzen; während mindestens 6 Monaten wird vorbeugend Colchicin oder ein NSAR empfohlen.","Leberwerte vor Beginn und regelmässig während der Behandlung kontrollieren.","Bei Brustschmerzen, Atemnot, Lähmungen oder Sprachstörungen sofort notfallmässig ärztliche Hilfe holen.","Unabhängig von den Mahlzeiten einnehmen."],"darreichung":["Filmtabletten"]},"felodipin":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Blutgefässe erweitert. Felodipin hemmt den Einstrom von Calcium durch L-Typ-Calciumkanäle in die glatte Muskulatur der Arterien und wirkt dabei sehr gefässselektiv, kaum am Herzmuskel. Dadurch sinkt der Gefässwiderstand; bei Angina pectoris verbessert sich das Verhältnis von Sauerstoffangebot und -bedarf des Herzens. Als Retardtablette wirkt es über 24 Stunden.","nebenwirkungen":{"sehrHaeufig":["Periphere Ödeme (geschwollene Knöchel und Beine)"],"haeufig":["Kopfschmerzen","Flush (Hitzegefühl, Gesichtsrötung)"],"gelegentlich":["Herzklopfen, beschleunigter Puls","Schwindel, Kribbeln (Parästhesien)","Übelkeit, Bauchschmerzen","Hautausschlag, Juckreiz","Müdigkeit"],"selten":["Ohnmacht (Synkope)","Erbrechen","Nesselsucht","Gelenk- und Muskelschmerzen","Impotenz, sexuelle Funktionsstörungen"],"sehrSelten":["Zahnfleischwucherung (Gingivahyperplasie), Zahnfleischentzündung","Erhöhte Leberwerte","Lichtempfindlichkeit der Haut","Gefässentzündung der Haut (leukozytoklastische Vaskulitis)","Angioödem, Fieber","Häufiges Wasserlassen"]},"schwangerschaft":"Kontraindiziert; im Tierversuch traten Fehlbildungen auf.","stillzeit":"Geht in die Muttermilch über; Stillen wird während der Behandlung nicht empfohlen.","hinweise":["Retardtablette morgens unzerkaut und ungeteilt mit Wasser schlucken, nüchtern oder mit einer leichten Mahlzeit.","Keinen Grapefruitsaft trinken.","Auf gute Mundhygiene achten (Zahnfleischwucherung).","Knöchelschwellungen sind häufig und harmlos, sollten aber bei Zunahme ärztlich besprochen werden."],"darreichung":["Retardtabletten"]},"fenofibrat":{"wirkmechanismus":"Senkt vor allem die Triglyceride (Neutralfette) und erhöht das «gute» HDL-Cholesterin. Fenofibrat ist ein Prodrug, das im Körper rasch zur aktiven Fenofibrinsäure umgewandelt wird. Diese aktiviert den Kernrezeptor PPAR-alpha: Die Lipoproteinlipase wird aktiviert und die Bildung von Apolipoprotein C-III gehemmt, sodass triglyceridreiche Lipoproteine (VLDL) schneller abgebaut werden; gleichzeitig steigt die Bildung der HDL-Bausteine Apolipoprotein A-I und A-II. Auch LDL-Cholesterin und Harnsäure sinken mässig.","nebenwirkungen":{"haeufig":["Magen-Darm-Beschwerden: Bauchschmerzen, Übelkeit, Erbrechen, Durchfall, Blähungen","Erhöhte Leberwerte (Transaminasen)","Erhöhtes Homocystein im Blut"],"gelegentlich":["Thromboembolien (Lungenembolie, tiefe Venenthrombose)","Kopfschmerzen","Pankreatitis (Bauchspeicheldrüsenentzündung)","Gallensteine","Hautausschlag, Juckreiz, Nesselsucht","Muskelbeschwerden (Muskelschmerzen, Myositis, Muskelkrämpfe, Muskelschwäche)","Sexuelle Funktionsstörungen","Erhöhtes Kreatinin"],"selten":["Hepatitis (Leberentzündung)","Photosensibilität (Lichtempfindlichkeit der Haut)","Haarausfall","Abfall von Hämoglobin und weissen Blutkörperchen","Überempfindlichkeitsreaktionen","Erhöhter Harnstoff"],"unbekannt":["Rhabdomyolyse (Muskelzerfall)","Schwere Hautreaktionen (Erythema multiforme, Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Gelbsucht; Komplikationen von Gallensteinen (Gallenblasen- und Gallenwegsentzündung, Gallenkolik)","Interstitielle Lungenerkrankung","Müdigkeit"]},"schwangerschaft":"Nur nach strenger ärztlicher Nutzen-Risiko-Abwägung – Erfahrungen beim Menschen fehlen weitgehend.","stillzeit":"Nicht anwenden – der Übergang in die Muttermilch ist nicht ausreichend untersucht.","hinweise":["Je nach Präparat mit einer Mahlzeit einnehmen – Angabe in der Packungsbeilage beachten.","Leber- und Nierenwerte regelmässig kontrollieren; Muskelschmerzen oder -schwäche sofort melden.","Starke Sonnen- und UV-Bestrahlung meiden (Lichtempfindlichkeit).","Diät, Gewichtsreduktion und Verzicht auf Alkohol bleiben wichtig, besonders bei hohen Triglyceriden."],"darreichung":["Kapseln","Filmtabletten"]},"fentanyl":{"wirkmechanismus":"Lindert sehr starke Schmerzen, indem es an die körpereigenen Opioid-Andockstellen in Gehirn und Rückenmark bindet. Fentanyl ist ein synthetischer, stark fettlöslicher Agonist am μ-Opioidrezeptor und etwa 100-mal stärker wirksam als Morphin. Es hemmt Weiterleitung und Wahrnehmung von Schmerzreizen, dämpft aber auch das Atemzentrum. Der Abbau erfolgt in der Leber überwiegend über CYP3A4 zum unwirksamen Norfentanyl.","nebenwirkungen":{"sehrHaeufig":["Schläfrigkeit, Schwindel","Kopfschmerzen","Übelkeit, Erbrechen","Obstipation (Verstopfung)"],"haeufig":["Überempfindlichkeitsreaktionen","Appetitlosigkeit","Schlaflosigkeit, Angst, Verwirrtheit, Halluzinationen","Zittern, Kribbeln","Herzklopfen, Herzrasen","Atemnot","Mundtrockenheit, Durchfall, Bauchschmerzen","Starkes Schwitzen, Juckreiz, Hautausschlag"],"gelegentlich":["Atemdepression (abgeschwächte Atmung)","Krampfanfälle, Bewusstseinsstörungen","Bradykardie (langsamer Puls), Blutdruckabfall","Ileus (Darmlähmung)","Erektionsstörung","Hautreaktionen an der Pflasterstelle","Entzugssymptome"],"selten":["Atemstillstand (Apnoe)","Miosis (enge Pupillen)"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Delir","Androgenmangel bei Langzeitanwendung","Serotonin-Syndrom","Abhängigkeit und Toleranz","Hyperalgesie (erhöhte Schmerzempfindlichkeit)"]},"schwangerschaft":"Nur wenn eindeutig erforderlich. Langdauernde Anwendung kann beim Neugeborenen ein Entzugssyndrom auslösen; während der Geburt nicht anwenden (Atemdepression beim Kind).","stillzeit":"Fentanyl geht in die Muttermilch über und kann beim Säugling Atemdepression verursachen. Während der Behandlung und mindestens 72 Stunden nach Entfernen des Pflasters nicht stillen.","hinweise":["Pflaster nicht zerschneiden und keiner Wärme aussetzen (Heizkissen, Sauna, heisses Bad); gebrauchte Pflaster mit der Klebeseite nach innen falten und für Kinder unerreichbar entsorgen.","Kein Alkohol; die Fahrtüchtigkeit ist vor allem zu Beginn und bei Dosisänderungen eingeschränkt.","Bei Atemproblemen oder ungewöhnlicher Schläfrigkeit sofort Hilfe holen; nach längerer Anwendung nicht abrupt absetzen.","Die verschiedenen Präparate gegen Durchbruchschmerzen sind nicht Mikrogramm für Mikrogramm austauschbar."],"darreichung":["Transdermale Pflaster","Buccaltabletten","Sublingualtabletten","Nasenspray","Injektionslösung"]},"fesoterodin":{"wirkmechanismus":"Entspannt den überaktiven Blasenmuskel, sodass die Blase mehr Urin speichern kann. Fesoterodin ist eine Vorstufe (Prodrug), die im Körper durch unspezifische Esterasen rasch in den eigentlichen Wirkstoff 5-Hydroxymethyltolterodin (5-HMT) umgewandelt wird – denselben aktiven Metaboliten wie bei Tolterodin. 5-HMT blockiert kompetitiv die Muskarinrezeptoren des Blasenmuskels und wird über CYP2D6 und CYP3A4 abgebaut.","nebenwirkungen":{"sehrHaeufig":["Mundtrockenheit"],"haeufig":["Schlaflosigkeit","Schwindel, Kopfschmerzen","Trockene Augen, trockener Hals","Bauchschmerzen, Durchfall, Verdauungsbeschwerden, Verstopfung, Übelkeit","Schmerzen beim Wasserlassen"],"gelegentlich":["Harnwegsinfektion","Geschmacksstörung, Schläfrigkeit","Verschwommenes Sehen","Drehschwindel","Herzrasen, Herzklopfen","Halsschmerzen, Husten, trockene Nase","Blähungen, Reflux","Anstieg der Leberwerte (ALT, GGT)","Hautausschlag, trockene Haut, Juckreiz","Harnverhalt, Restharn, verzögertes Wasserlassen","Müdigkeit"],"selten":["Angioödem","Verwirrtheit","Nesselsucht"]},"schwangerschaft":"Nicht empfohlen – es liegen keine ausreichenden Daten vor.","stillzeit":"Nicht anwenden – es ist nicht bekannt, ob der Wirkstoff in die Muttermilch übergeht.","hinweise":["Retardtabletten einmal täglich ganz mit Flüssigkeit schlucken, nicht teilen oder zerkauen.","Die volle Wirkung zeigt sich nach etwa 2–8 Wochen.","Verschwommenes Sehen, Schwindel und Schläfrigkeit können die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Retardtabletten"]},"fexofenadin":{"wirkmechanismus":"Blockiert die Wirkung von Histamin und lindert dadurch allergische Beschwerden wie Niesen, Juckreiz und Quaddeln. Fexofenadin ist der aktive Metabolit von Terfenadin, jedoch ohne dessen herzschädigende Wirkung, und ein selektiver Antagonist peripherer Histamin-H1-Rezeptoren. Es gelangt kaum ins Gehirn und macht daher praktisch nicht müde. Fexofenadin wird kaum verstoffwechselt; Aufnahme und Ausscheidung hängen von Transportproteinen wie P-Glykoprotein und OATP ab.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Schläfrigkeit","Schwindel","Übelkeit"],"gelegentlich":["Müdigkeit"],"unbekannt":["Überempfindlichkeitsreaktionen mit Angioödem, Engegefühl in der Brust, Atemnot, Hitzegefühl bis Anaphylaxie","Schlaflosigkeit, Nervosität, Albträume","Herzrasen (Tachykardie), Herzklopfen","Durchfall","Hautausschlag, Nesselsucht, Juckreiz","Verschwommenes Sehen"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur anwenden, wenn es ärztlich klar notwendig ist.","stillzeit":"Geht vermutlich in die Muttermilch über; Anwendung in der Stillzeit nicht empfohlen.","hinweise":["Mit Wasser vor einer Mahlzeit einnehmen, nicht mit Fruchtsaft.","Zu Antazida (Magensäurebindern) mindestens 2 Stunden Abstand halten.","Macht in der Regel nicht müde; die eigene Reaktion vor dem Autofahren trotzdem prüfen."],"darreichung":["Filmtabletten"]},"fidaxomicin":{"wirkmechanismus":"Tötet das Darmbakterium Clostridioides difficile ab und schont dabei weitgehend die übrige Darmflora. Fidaxomicin hemmt die bakterielle RNA-Polymerase und wirkt dadurch bakterizid. Es hat ein schmales Wirkspektrum und hemmt zudem die Sporenbildung, weshalb Rückfälle seltener auftreten als unter Vancomycin. Der Wirkstoff wird kaum ins Blut aufgenommen und wirkt im Darm.","nebenwirkungen":{"haeufig":["Übelkeit","Erbrechen","Verstopfung"],"gelegentlich":["Verminderter Appetit","Schwindel","Kopfschmerzen","Geschmacksstörung","Aufgeblähter Bauch, Blähungen","Mundtrockenheit","Erhöhte Leberwerte","Hautausschlag, Juckreiz"],"unbekannt":["Überempfindlichkeitsreaktionen wie Angioödem und Atemnot"]},"schwangerschaft":"Keine ausreichenden Daten; aus Vorsicht in der Schwangerschaft möglichst nicht anwenden.","stillzeit":"Nicht bekannt, ob Fidaxomicin in die Muttermilch übergeht; da es kaum ins Blut gelangt, ist eine Anwendung nach ärztlicher Abwägung möglich.","hinweise":["Unabhängig von den Mahlzeiten einnehmen und die Behandlung (meist 10 Tage) nicht vorzeitig abbrechen.","Bei Schwellungen von Gesicht, Lippen oder Zunge oder bei Atemnot sofort ärztliche Hilfe holen.","Erneuten Durchfall nach Behandlungsende (möglicher Rückfall) ärztlich melden."],"darreichung":["Filmtabletten"]},"filgrastim":{"wirkmechanismus":"Regt das Knochenmark an, mehr infektabwehrende weisse Blutkörperchen (neutrophile Granulozyten) zu bilden und ins Blut abzugeben. Filgrastim ist ein gentechnisch hergestellter humaner G-CSF, der an den G-CSF-Rezeptor auf Vorläuferzellen der Granulozyten bindet. Dadurch werden Vermehrung, Ausreifung und Funktion der Neutrophilen gesteigert; die Zahl der Neutrophilen steigt innerhalb von 24 Stunden an. In höheren Dosen werden zudem Blutstammzellen aus dem Knochenmark ins Blut ausgeschwemmt.","nebenwirkungen":{"sehrHaeufig":["Knochen- und Muskelschmerzen","Kopfschmerzen","Übelkeit, Erbrechen, Durchfall","Thrombozytopenie (Mangel an Blutplättchen) und Anämie (Blutarmut)","Fieber, Müdigkeit","Haarausfall und Schleimhautentzündung (im Rahmen der Chemotherapie)"],"haeufig":["Milzvergrösserung","Erhöhte Werte von LDH und alkalischer Phosphatase im Blut","Blutdruckabfall oder Blutdruckanstieg","Husten, Atemnot, Bluthusten (Hämoptyse)","Hautausschlag, Hautrötung","Schmerzen beim Wasserlassen (Dysurie)"],"gelegentlich":["Milzriss (Milzruptur)","Sichelzellkrisen bei Sichelzellkrankheit","Überempfindlichkeitsreaktionen","ARDS (akutes Lungenversagen), Lungeninfiltrate, Lungenblutung","Sweet-Syndrom (akute fieberhafte Hauterkrankung)","Hautvaskulitis (Gefässentzündung)","Glomerulonephritis (Nierenentzündung), Eiweiss im Urin","Pseudogicht und erhöhte Harnsäure"],"selten":["Kapillarlecksyndrom","Aortitis (Entzündung der Hauptschlagader)","Anaphylaxie (schwere allergische Reaktion)"],"unbekannt":["Myelodysplastisches Syndrom oder akute myeloische Leukämie (bei bestimmten Patientengruppen)"]},"schwangerschaft":"Erfahrungen sind begrenzt; nur nach strenger ärztlicher Nutzen-Risiko-Abwägung anwenden.","stillzeit":"Ob Filgrastim in die Muttermilch übergeht, ist nicht bekannt; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Bei Schmerzen im linken Oberbauch oder in der linken Schulterspitze sofort ärztliche Hilfe holen (möglicher Milzriss).","Knochenschmerzen sind häufig und lassen sich meist mit einfachen Schmerzmitteln wie Paracetamol lindern.","Während der Behandlung wird das Blutbild regelmässig kontrolliert.","Fertigspritzen im Kühlschrank lagern, nicht einfrieren."],"darreichung":["Injektions- oder Infusionslösung (Fertigspritze, Durchstechflasche)"]},"finasterid":{"wirkmechanismus":"Verkleinert die Prostata bzw. bremst den Haarausfall, indem es die Bildung des stark wirksamen männlichen Hormons Dihydrotestosteron (DHT) vermindert. Finasterid hemmt spezifisch das Enzym 5-Alpha-Reduktase Typ 2, das in Prostata, Haarwurzeln und Haut Testosteron in DHT umwandelt. Der DHT-Spiegel im Blut sinkt um rund 70 %, in der Prostata noch stärker, während der Testosteronspiegel weitgehend unverändert bleibt. Die Prostata schrumpft langsam über Monate; beim Haarausfall ist eine Wirkung frühestens nach 3–6 Monaten zu erwarten.","nebenwirkungen":{"haeufig":["Erektionsstörung (Impotenz) – bei 1 mg gelegentlich","Verminderte Libido (Lust auf Sex) – bei 1 mg gelegentlich","Vermindertes Ejakulatvolumen"],"gelegentlich":["Ejakulationsstörungen","Spannungsgefühl oder Vergrösserung der Brust (Gynäkomastie)","Hautausschlag"],"unbekannt":["Depression, Angst, Suizidgedanken","Sexuelle Funktionsstörungen, die nach dem Absetzen anhalten","Hodenschmerzen, Blut im Sperma","Männliche Unfruchtbarkeit, verminderte Spermienqualität","Überempfindlichkeitsreaktionen mit Juckreiz, Nesselsucht, Angioödem","Herzklopfen","Erhöhte Leberwerte","Brustkrebs beim Mann"]},"schwangerschaft":"Kontraindiziert. Schwangere und Frauen, die schwanger werden könnten, dürfen zerbrochene oder zerdrückte Tabletten nicht berühren: der Wirkstoff kann über die Haut aufgenommen werden und bei einem männlichen Fötus Fehlbildungen der Geschlechtsorgane verursachen.","stillzeit":"Nicht für Frauen bestimmt.","hinweise":["Ganze, unbeschädigte Filmtabletten sind beim Berühren unbedenklich; zerbrochene Tabletten von Schwangeren fernhalten.","Die Wirkung tritt erst nach Monaten ein: gegen Haarausfall mindestens 3–6 Monate regelmässig einnehmen; nach dem Absetzen geht der Effekt innerhalb etwa eines Jahres wieder verloren.","Bei einer PSA-Bestimmung die Einnahme angeben, da der Wert halbiert wird.","Stimmungsveränderungen oder anhaltende sexuelle Probleme ärztlich besprechen."],"darreichung":["Filmtabletten"]},"finerenon":{"wirkmechanismus":"Schützt Nieren und Herz, indem es die überaktiven Signale des Hormons Aldosteron blockiert. Finerenon ist ein nichtsteroidaler, hochselektiver Antagonist des Mineralokortikoid-Rezeptors, dessen Überaktivierung Entzündung und Fibrose (Vernarbung) in Niere, Herz und Gefässen fördert. Es vermindert so die Eiweissausscheidung im Urin und verlangsamt den Verlust der Nierenfunktion. Den Blutdruck senkt es nur wenig, und an Androgen- oder Progesteronrezeptoren bindet es praktisch nicht. Finerenon wird überwiegend über CYP3A4 abgebaut.","nebenwirkungen":{"sehrHaeufig":["Hyperkaliämie (erhöhtes Kalium)"],"haeufig":["Hyponatriämie (Natriummangel)","Hypotonie (niedriger Blutdruck)","Juckreiz","Abnahme der glomerulären Filtrationsrate (Nierenfunktion), meist zu Beginn und rückbildungsfähig"],"gelegentlich":["Abnahme des Hämoglobins (Blutfarbstoff)"]},"schwangerschaft":"Nicht anwenden, ausser bei zwingender Notwendigkeit (im Tierversuch fruchtschädigend); Frauen im gebärfähigen Alter müssen während der Behandlung zuverlässig verhüten.","stillzeit":"Ein Risiko für den Säugling kann nicht ausgeschlossen werden; während der Behandlung nicht stillen.","hinweise":["Kalium und Nierenfunktion vor Beginn, nach 4 Wochen und danach regelmässig kontrollieren lassen.","Grapefruit und Grapefruitsaft meiden; keine Kaliumpräparate oder kaliumhaltigen Salzersatzmittel ohne Rücksprache.","Vor jedem neuen Medikament, besonders Antibiotika, Pilzmitteln und Johanniskraut, auf Finerenon hinweisen.","Tablette kann bei Schluckbeschwerden zerdrückt und mit Wasser oder weicher Nahrung (z. B. Apfelmus) eingenommen werden."],"darreichung":["Filmtabletten"]},"flecainid":{"wirkmechanismus":"Bremst die elektrische Erregungsleitung im Herzen und verhindert dadurch kreisende Erregungen, die Herzrasen auslösen. Flecainid blockiert die schnellen Natriumkanäle der Herzmuskelzellen stark und löst sich nur langsam wieder von ihnen (Klasse IC). Dadurch werden die Leitungsgeschwindigkeit in Vorhöfen, AV-Knoten, His-Purkinje-System, Kammern und zusätzlichen Leitungsbahnen deutlich verlangsamt (im EKG Verbreiterung von PR- und QRS-Intervall). Flecainid wird teilweise über CYP2D6 abgebaut und zu einem grossen Teil über die Niere ausgeschieden.","nebenwirkungen":{"sehrHaeufig":["Schwindel, Benommenheit","Sehstörungen (Doppelbilder, verschwommenes Sehen, Schwierigkeiten beim Scharfstellen)"],"haeufig":["Neu ausgelöste oder verstärkte Herzrhythmusstörungen (Proarrhythmie), besonders bei struktureller Herzerkrankung","Atemnot","Schwäche, Müdigkeit","Fieber","Ödeme (Wassereinlagerungen)"],"gelegentlich":["Übelkeit, Erbrechen, Verstopfung, Bauchschmerzen, Durchfall, Blähungen","Appetitlosigkeit","Verminderung von roten und weissen Blutkörperchen sowie Blutplättchen","Allergische Hautreaktionen, Haarausfall"],"selten":["Halluzinationen, Depression, Verwirrtheit, Angst, Schlaflosigkeit","Kribbeln, Gangunsicherheit, Zittern, Ohnmacht (Synkope), Krampfanfälle","Periphere Neuropathie (Nervenschädigung)","Ohrensausen (Tinnitus), Drehschwindel","Pneumonitis (Lungenentzündung ohne Erreger)","Erhöhte Leberwerte, Gelbsucht","Nesselsucht"],"sehrSelten":["Hornhautablagerungen","Lichtempfindlichkeit der Haut"],"unbekannt":["AV-Block 2. und 3. Grades, Sinusarrest, Bradykardie, Kammerflimmern, Herzstillstand","Verschlechterung einer Herzinsuffizienz, Blutdruckabfall","Demaskierung eines Brugada-Syndroms","Lungenfibrose und interstitielle Lungenerkrankung"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung: Flecainid gelangt zum Ungeborenen, und in Tierversuchen traten Fehlbildungen auf.","stillzeit":"Geht in die Muttermilch über; Anwendung in der Stillzeit nur nach ärztlicher Abwägung.","hinweise":["Die Behandlung wird unter EKG-Kontrolle begonnen; regelmässige EKG- und bei eingeschränkter Nierenfunktion Spiegelkontrollen.","Bei neuem Herzrasen, Ohnmacht, Atemnot oder Wassereinlagerungen sofort ärztliche Hilfe holen.","Jedes neue Medikament ärztlich auf Wechselwirkungen prüfen lassen, besonders Antidepressiva und Antibiotika.","Durchfall oder Erbrechen können den Kaliumspiegel senken und das Risiko von Rhythmusstörungen erhöhen."],"darreichung":["Tabletten"]},"flohsamenschalen-ispaghula":{"wirkmechanismus":"Quillt im Darm auf und vergrössert dadurch die Stuhlmenge, die den Darm auf natürliche Weise zur Entleerung anregt. Die Schalen der Samen von Plantago ovata enthalten Schleimstoffe (Arabinoxylane), die ein Vielfaches ihres Gewichts an Wasser binden und ein Gel bilden. Dieses macht harten Stuhl weicher und gleitfähiger, dehnt die Darmwand und regt so die Peristaltik an. Bei dünnem Stuhl kann das Gel überschüssiges Wasser binden. Die Wirkung tritt nach 12–72 Stunden ein; die Schleimstoffe werden nicht ins Blut aufgenommen.","nebenwirkungen":{"unbekannt":["Blähungen und Völlegefühl, vor allem zu Beginn","Bauchschmerzen","Darm- oder Speiseröhrenverschluss sowie Kotstau bei zu wenig Flüssigkeit","Überempfindlichkeitsreaktionen wie Schnupfen, Bindehautentzündung, Asthma, Hautausschlag, Juckreiz","Anaphylaxie (schwere allergische Reaktion), selten"]},"schwangerschaft":"Kann angewendet werden; die Schleimstoffe werden nicht ins Blut aufgenommen. Gilt bei Verstopfung in der Schwangerschaft als Mittel der ersten Wahl.","stillzeit":"Kann angewendet werden.","hinweise":["Jede Dosis in einem grossen Glas Wasser (mindestens 150 ml) einrühren, sofort trinken und reichlich nachtrinken – zu wenig Flüssigkeit kann Speiseröhre oder Darm verstopfen.","Nicht unmittelbar vor dem Schlafengehen und nicht im Liegen einnehmen.","Andere Medikamente mit zeitlichem Abstand einnehmen (mindestens 30–60 Minuten).","Die volle Wirkung kann 1–3 Tage dauern; Blähungen bessern sich meist nach einigen Tagen."],"darreichung":["Pulver","Granulat"]},"flucloxacillin":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand verhindert. Flucloxacillin hemmt die Penicillin-bindenden Proteine und damit die Quervernetzung des Peptidoglykans (bakterizide Wirkung). Dank seiner Seitenkette ist es gegen die Penicillinase (Beta-Laktamase) der Staphylokokken stabil und deshalb ein Mittel der Wahl bei Infektionen mit Methicillin-empfindlichem Staphylococcus aureus. Gegen MRSA, Enterokokken und die meisten gramnegativen Bakterien wirkt es nicht.","nebenwirkungen":{"haeufig":["Leichte Magen-Darm-Beschwerden (Übelkeit, Durchfall, Bauchschmerzen)"],"gelegentlich":["Hautausschlag, Nesselsucht, Purpura (punktförmige Hautblutungen)"],"sehrSelten":["Leberentzündung und Gelbsucht durch Gallestau (auch verzögert bis 2 Monate nach Behandlungsende, teils langwierig)","Neutropenie bis Agranulozytose, Thrombozytopenie","Anaphylaxie und Angioödem","Pseudomembranöse Kolitis (schwere Darmentzündung)","Schwere Hautreaktionen (Erythema multiforme, Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Gelenk- und Muskelschmerzen, Fieber","Interstitielle Nephritis (Nierenentzündung)"],"unbekannt":["Metabolische Azidose mit erhöhter Anionenlücke (vor allem zusammen mit Paracetamol)","Eosinophilie","Akute generalisierte exanthematische Pustulose (AGEP)","Venenreizung an der Infusionsstelle"]},"schwangerschaft":"Nach ärztlicher Abwägung möglich; bisher keine Hinweise auf eine Schädigung des Kindes.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Anwendung nach Abwägung möglich (beim Säugling Durchfall oder Sensibilisierung möglich).","hinweise":["Kapseln nüchtern mit einem Glas Wasser einnehmen: mindestens 1 Stunde vor oder 2 Stunden nach dem Essen.","Gelbe Haut oder Augen, dunkler Urin oder heller Stuhl – auch Wochen nach Behandlungsende – sofort ärztlich abklären lassen.","Paracetamol nur nach ärztlicher Rücksprache gleichzeitig einnehmen.","Bei einer Behandlung über mehr als 14 Tage werden die Leberwerte kontrolliert."],"darreichung":["Kapseln","Pulver zur Herstellung einer Injektions- oder Infusionslösung"]},"fluconazol":{"wirkmechanismus":"Hemmt die Bildung eines wichtigen Bausteins der Pilzzellwand und stoppt so das Pilzwachstum. Fluconazol blockiert das pilzeigene Cytochrom-P450-Enzym Lanosterol-14α-Demethylase, wodurch kein Ergosterol mehr für die Zellmembran gebildet wird und sich toxische Sterolvorstufen anreichern. Es wird gut aufgenommen, verteilt sich auch in Liquor und Urin und wird überwiegend unverändert über die Niere ausgeschieden. Fluconazol hemmt auch menschliche Leberenzyme (stark CYP2C19 und CYP2C9, mässig CYP3A4) und verursacht dadurch zahlreiche Wechselwirkungen.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Bauchschmerzen, Übelkeit, Erbrechen, Durchfall","Erhöhte Leberwerte (ALT, AST, alkalische Phosphatase)","Hautausschlag"],"gelegentlich":["Anämie (Blutarmut)","Appetitlosigkeit","Schlaflosigkeit, Schläfrigkeit","Krampfanfälle, Schwindel, Kribbeln, Geschmacksstörungen","Verstopfung, Verdauungsbeschwerden, Blähungen, Mundtrockenheit","Cholestase, Gelbsucht, erhöhtes Bilirubin","Juckreiz, Nesselsucht, vermehrtes Schwitzen, fixes Arzneimittelexanthem","Muskelschmerzen, Müdigkeit, Fieber"],"selten":["Agranulozytose, Leukopenie, Neutropenie, Thrombozytopenie","Anaphylaxie und Angioödem","Hypokaliämie (Kaliummangel), erhöhte Blutfette","Zittern (Tremor)","QT-Verlängerung, Torsade de pointes (lebensgefährliche Herzrhythmusstörung)","Leberversagen, Hepatitis, Lebernekrose","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, AGEP), Haarausfall"],"unbekannt":["DRESS (Arzneimittelreaktion mit Eosinophilie und Organbeteiligung)","Nebenniereninsuffizienz"]},"schwangerschaft":"Nicht anwenden, ausser bei schweren oder lebensbedrohlichen Pilzinfektionen. Hohe Dosen (400–800 mg pro Tag) über Wochen im ersten Drittel wurden mit Fehlbildungen in Verbindung gebracht; auch eine Einmaldosis im ersten Drittel ist mit einem leicht erhöhten Fehlgeburtsrisiko assoziiert – bei Scheidenpilz lokale Mittel bevorzugen.","stillzeit":"Geht in ähnlicher Konzentration wie im Blut in die Muttermilch über. Nach einer Einzeldosis von 150 mg kann weiter gestillt werden; bei wiederholter oder hoch dosierter Behandlung wird Stillen nicht empfohlen.","hinweise":["Wegen der langen Halbwertszeit bestehen Wechselwirkungen noch 4–5 Tage nach der letzten Einnahme.","Kann unabhängig von den Mahlzeiten eingenommen werden.","Schwindel oder Krampfanfälle möglich – Vorsicht beim Autofahren.","Bei längerer Behandlung Leberwerte kontrollieren; bei Gelbsucht, dunklem Urin oder starkem Ausschlag ärztlich melden."],"darreichung":["Kapseln","Pulver für Suspension zum Einnehmen","Infusionslösung"]},"fludrocortison":{"wirkmechanismus":"Ersetzt das Hormon Aldosteron, das bei Nebenniereninsuffizienz fehlt, und sorgt dafür, dass die Niere Salz und Wasser zurückhält. Fludrocortison bindet an Mineralokortikoid-Rezeptoren im Endabschnitt der Nierenkanälchen und steigert dort die Rückgewinnung von Natrium sowie die Ausscheidung von Kalium und Wasserstoffionen. Dadurch normalisieren sich Blutvolumen, Blutdruck und Salzhaushalt. Die mineralokortikoide Wirkung ist sehr stark; die glukokortikoide (entzündungshemmende) Wirkung spielt in den üblichen niedrigen Dosen keine Rolle.","nebenwirkungen":{"unbekannt":["Salz- und Wasserretention mit Ödemen und Gewichtszunahme","Bluthochdruck","Hypokaliämie (Kaliummangel) und hypokaliämische Alkalose","Herzinsuffizienz, Herzvergrösserung","Muskelschwäche","Kopfschmerzen","Bei höheren Dosen glukokortikoidtypische Wirkungen (z. B. Osteoporose, erhöhter Blutzucker, Infektanfälligkeit)","Überempfindlichkeitsreaktionen (Hautausschlag)"]},"schwangerschaft":"Eine notwendige Ersatztherapie bei Nebenniereninsuffizienz wird auch in der Schwangerschaft weitergeführt; Dosis ärztlich überwachen.","stillzeit":"Nur nach ärztlicher Abwägung; eine notwendige Ersatztherapie wird in der Regel weitergeführt.","hinweise":["Nie eigenmächtig absetzen; immer zusammen mit dem verordneten Glukokortikoid (z. B. Hydrocortison) einnehmen.","Notfallausweis für Nebenniereninsuffizienz mitführen; bei Fieber, Erbrechen oder vor Operationen ärztlich die Glukokortikoid-Dosis anpassen lassen.","Regelmässig Blutdruck, Gewicht, Kalium und Natrium kontrollieren: Salzhunger und Schwindel beim Aufstehen sprechen für eine zu tiefe, Ödeme und Bluthochdruck für eine zu hohe Dosis."],"darreichung":["Tabletten"]},"flumazenil":{"wirkmechanismus":"Hebt die beruhigende, schlafmachende und atemdämpfende Wirkung von Benzodiazepinen auf. Flumazenil ist ein Imidazobenzodiazepin, das die Benzodiazepin-Bindungsstelle am GABA-A-Rezeptor kompetitiv besetzt, ohne sie nennenswert zu aktivieren. Es verdrängt so Benzodiazepine und auch Z-Substanzen wie Zolpidem und Zopiclon. Die Wirkung tritt innert 1–2 Minuten ein, hält aber wegen der kurzen Halbwertszeit von etwa einer Stunde oft kürzer an als die des Benzodiazepins.","nebenwirkungen":{"sehrHaeufig":["Übelkeit"],"haeufig":["Angst, Stimmungsschwankungen, Schlaflosigkeit","Schwindel, Kopfschmerzen, Zittern, Unruhe","Doppelbilder, vermehrter Tränenfluss","Herzklopfen, Hitzewallungen, Blutdruckabfall","Erbrechen, Schluckauf, Schwitzen","Müdigkeit, Schmerzen an der Injektionsstelle"],"gelegentlich":["Krampfanfälle (v. a. bei Epilepsie oder schwerer Leberinsuffizienz)","Herzrasen, verlangsamter Puls, Extrasystolen","Atemnot, Husten","Hörstörungen","Frösteln"],"selten":["Vorübergehender Blutdruckanstieg"],"unbekannt":["Überempfindlichkeitsreaktionen bis zur Anaphylaxie","Entzugssymptome nach Benzodiazepin-Langzeitanwendung","Panikattacken bei Menschen mit Panikstörung"]},"schwangerschaft":"Erfahrungen fehlen; nur bei klarer Notwendigkeit anwenden. Im Notfall ist die Anwendung nicht kontraindiziert.","stillzeit":"Ob Flumazenil in die Muttermilch übergeht, ist nicht bekannt; im Notfall ist die Anwendung nicht kontraindiziert.","hinweise":["Da die Benzodiazepinwirkung zurückkehren kann, bleiben Patientinnen und Patienten nach der Gabe unter Überwachung.","Nach der Behandlung mindestens 24 Stunden nicht Auto fahren, keine Maschinen bedienen und keinen Alkohol trinken.","Wird nur von Fachpersonen im Spital oder in der Notfallmedizin angewendet."],"darreichung":["Injektionslösung"]},"fluocinonid":{"wirkmechanismus":"Dämpft Entzündung, Rötung, Schwellung und Juckreiz der Haut. Fluocinonid ist ein fluoriertes, stark wirksames Glukokortikoid: Es bindet an Glukokortikoid-Rezeptoren in den Hautzellen und hemmt die Bildung entzündungsfördernder Botenstoffe wie Prostaglandine, Leukotriene und Zytokine. Zusätzlich verengt es die Blutgefässe der Haut und bremst die Zellteilung in der Oberhaut. Bei grossflächiger oder langer Anwendung kann so viel Wirkstoff durch die Haut aufgenommen werden, dass Wirkungen im ganzen Körper auftreten.","nebenwirkungen":{"unbekannt":["Brennen, Juckreiz oder Reizung an der Auftragsstelle","Hautatrophie (Hautverdünnung), Teleangiektasien (erweiterte Äderchen), Dehnungsstreifen (Striae)","Steroidakne, periorale Dermatitis (Ausschlag um den Mund)","Hellere Hautstellen (Hypopigmentierung), vermehrte Behaarung","Allergische Kontaktdermatitis","Sekundäre Hautinfektionen durch Bakterien oder Pilze","Verschwommenes Sehen (z. B. durch Chorioretinopathie)","Bei grossflächiger oder langer Anwendung: Unterdrückung der Nebennierenrinde, Cushing-Syndrom, bei Kindern Wachstumsverzögerung"]},"schwangerschaft":"Nur nach ärztlicher Abwägung, kleinflächig und kurzzeitig; nicht grossflächig, nicht langfristig und nicht unter luftdichten Verbänden anwenden.","stillzeit":"Kleinflächige, kurzzeitige Anwendung nach ärztlicher Abwägung möglich; nicht im Brustbereich auftragen, damit der Säugling den Wirkstoff nicht aufnimmt.","hinweise":["Dünn auftragen und nur so lange wie nötig anwenden; im Gesicht nur auf ärztliche Anweisung.","Nicht in die Augen bringen; nach dem Auftragen die Hände waschen.","Keine luftdichten Verbände ohne ärztliche Anweisung.","Nach längerer Anwendung nicht abrupt absetzen, sondern schrittweise reduzieren (Rückfallgefahr)."],"darreichung":["Creme","Salbe","Lösung zur Anwendung auf der Kopfhaut"]},"fluocortolon":{"wirkmechanismus":"Lindert Entzündung, Schwellung und Juckreiz am After. Fluocortolon ist ein stark wirksames Glukokortikoid, das über den Glukokortikoid-Rezeptor die Bildung entzündungsfördernder Botenstoffe (z. B. Prostaglandine, Zytokine) hemmt und die Durchlässigkeit kleiner Gefässe vermindert. In den Kombipräparaten sorgt ein Lokalanästhetikum (Lidocain bzw. Cinchocain) für eine rasche Schmerzlinderung.","nebenwirkungen":{"unbekannt":["Lokales Brennen oder Reizung","Allergische Hautreaktionen","Bei Anwendung über mehrere Wochen: Hautverdünnung (Atrophie), Dehnungsstreifen (Striae), erweiterte Äderchen (Teleangiektasien)","Verschwommenes Sehen (Kortison-Klasseneffekt)"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung, besonders im ersten Schwangerschaftsdrittel; dann kurz und kleinflächig anwenden.","stillzeit":"Kurzfristige Anwendung nach ärztlicher Abwägung möglich; es gelangen nur geringe Mengen in den Körper.","hinweise":["Nicht länger als nötig und ohne ärztliche Kontrolle nicht über mehrere Wochen anwenden.","Zäpfchen nach dem Stuhlgang einführen; durch Wärme weich gewordene Zäpfchen kurz kühlen.","Kann die Reissfestigkeit von Latexkondomen vermindern.","Blut im Stuhl immer ärztlich abklären lassen."],"darreichung":["Rektalcreme","Salbe","Zäpfchen"]},"fluorouracil":{"wirkmechanismus":"Hemmt die Teilung schnell wachsender Zellen, indem es die Herstellung von Erbgut stört. Fluorouracil wird in der Zelle zu FdUMP umgewandelt, das die Thymidylat-Synthase blockiert und so die DNA-Synthese hemmt; als FUTP wird es zudem fehlerhaft in die RNA eingebaut. Folinsäure verstärkt die Hemmung der Thymidylat-Synthase. Der Abbau erfolgt über das Enzym Dihydropyrimidin-Dehydrogenase (DPD); bei DPD-Mangel drohen schwere, teils tödliche Vergiftungen. Auf der Haut zerstört es gezielt die sich rasch teilenden, krankhaft veränderten Zellen.","nebenwirkungen":{"sehrHaeufig":["Knochenmarkhemmung (Neutropenie, Thrombozytopenie, Anämie)","Entzündungen der Schleimhäute in Mund, Speiseröhre und Darm","Durchfall, Übelkeit, Erbrechen, Appetitlosigkeit","Haarausfall","Hand-Fuss-Syndrom (schmerzhafte Rötung von Handflächen und Fusssohlen)","Müdigkeit, Schwäche","Creme/Lösung: Rötung, Brennen, Schmerzen, Krusten und Erosionen an der behandelten Haut (erwartete Reaktion)"],"haeufig":["Fieber bei Neutropenie (febrile Neutropenie)","Brustschmerzen und Durchblutungsstörungen des Herzens (EKG-Veränderungen)"],"gelegentlich":["Herzrhythmusstörungen, Herzinfarkt, Herzmuskelentzündung, Herzinsuffizienz","Magen-Darm-Geschwüre und -Blutungen","Sepsis (Blutvergiftung), Flüssigkeitsmangel","Augenbeschwerden (Tränenfluss, verschwommenes Sehen, Augenzittern)","Kopfschmerzen, Schwindel, Bewegungsstörungen","Hautausschlag, Lichtempfindlichkeit, Pigment- und Nagelveränderungen"],"selten":["Anaphylaxie (schwere allergische Reaktion)"],"sehrSelten":["Leukenzephalopathie (Schädigung der weissen Hirnsubstanz)","Herzstillstand, plötzlicher Herztod","Akutes Nierenversagen"],"unbekannt":["Hyperammonämische Enzephalopathie (Verwirrtheit durch erhöhtes Ammoniak)"]},"schwangerschaft":"Kontraindiziert, auch als Creme oder Lösung (fruchtschädigend). Frauen und Männer müssen während und einige Monate nach einer Behandlung zuverlässig verhüten.","stillzeit":"Kontraindiziert.","hinweise":["Vor einer Infusionstherapie wird auf einen DPD-Mangel getestet.","Kein Brivudin (Gürtelrosemittel) während der Behandlung sowie in den 4 Wochen davor und danach – auch nicht bei Anwendung der Creme.","Creme nur auf die betroffenen Hautstellen auftragen, danach Hände waschen; Sonne meiden. Die gewollte Hautentzündung heilt nach Behandlungsende ab.","Bei starkem Durchfall, Mundgeschwüren, Fieber oder Brustschmerzen sofort ärztlich melden."],"darreichung":["Creme","Lösung zum Auftragen auf die Haut","Injektions- bzw. Infusionslösung"]},"fluoxetin":{"wirkmechanismus":"Hellt die Stimmung auf und vermindert Zwangsgedanken und Essattacken, indem es die Menge des Botenstoffs Serotonin zwischen den Nervenzellen erhöht. Fluoxetin hemmt selektiv den Serotonin-Transporter und damit die Wiederaufnahme von Serotonin in die Nervenzelle. Fluoxetin und sein wirksames Abbauprodukt Norfluoxetin haben sehr lange Halbwertszeiten (Tage bis Wochen), weshalb Wirkung und Wechselwirkungen nach dem Absetzen noch wochenlang anhalten. Fluoxetin hemmt zudem stark das Abbauenzym CYP2D6.","nebenwirkungen":{"sehrHaeufig":["Schlaflosigkeit","Kopfschmerzen","Übelkeit, Durchfall","Müdigkeit"],"haeufig":["Appetitlosigkeit, Gewichtsabnahme","Angst, Nervosität, Unruhe, ungewöhnliche Träume","Verminderte Libido, Erektions- und Ejakulationsstörungen","Schwindel, Schläfrigkeit, Zittern, Konzentrations- und Geschmacksstörungen","Verschwommenes Sehen, Herzklopfen, Hitzewallungen","Mundtrockenheit, Erbrechen, Verdauungsbeschwerden","Hautausschlag, Juckreiz, Nesselsucht, vermehrtes Schwitzen","Gelenkschmerzen, häufiges Wasserlassen, gynäkologische Blutungen"],"gelegentlich":["Suizidgedanken und suizidales Verhalten","Gehobene Stimmung, Depersonalisation, Zähneknirschen (Bruxismus)","Muskelzuckungen, Gangunsicherheit, Gedächtnisstörungen","Erweiterte Pupillen (Mydriasis), Ohrgeräusche (Tinnitus)","Blutdruckabfall","Atemnot, Nasenbluten","Magen-Darm-Blutungen, Schluckbeschwerden","Haarausfall, Neigung zu Blutergüssen"],"selten":["Hyponatriämie (Natriummangel)","Manie, Halluzinationen, Panikattacken, Aggressivität, Verwirrtheit","Krampfanfälle, Akathisie (Bewegungsunruhe), Serotoninsyndrom","QT-Verlängerung, ventrikuläre Herzrhythmusstörungen inkl. Torsade de pointes","Leberentzündung (Hepatitis)","Angioödem, Lichtempfindlichkeit, schwere Hautreaktionen (Erythema multiforme, Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Blutbildveränderungen (Thrombozytopenie, Neutropenie), anaphylaktische Reaktionen","Milchfluss (Galaktorrhö), Priapismus (Dauererektion), Harnverhalt"],"unbekannt":["Erhöhtes Risiko für Knochenbrüche","Nachblutungen nach der Geburt (bei Einnahme im letzten Monat der Schwangerschaft)"]},"schwangerschaft":"Nur nach sorgfältiger ärztlicher Abwägung: nach Einnahme im ersten Drittel wurde ein leicht erhöhtes Risiko für Herzfehler beobachtet, bei Einnahme in der Spätschwangerschaft sind beim Neugeborenen Anpassungsstörungen und Lungenhochdruck (PPHN) möglich. Nicht eigenmächtig absetzen.","stillzeit":"Fluoxetin und Norfluoxetin gehen in die Muttermilch über, beim Säugling wurden Nebenwirkungen beobachtet; Stillen nur nach ärztlicher Abwägung mit der tiefsten wirksamen Dosis.","hinweise":["Die Wirkung setzt nach 2–4 Wochen ein; zunehmende Unruhe oder Suizidgedanken in den ersten Wochen sofort ärztlich melden.","Wegen der langen Wirkdauer bestehen Wechselwirkungen noch bis zu 5 Wochen nach dem Absetzen (z. B. vor Beginn eines MAO-Hemmers).","Nicht abrupt absetzen, auch wenn Absetzsymptome seltener sind als bei anderen SSRI.","Kann die Fahrtüchtigkeit beeinträchtigen; Alkohol meiden."],"darreichung":["Kapseln","Tabletten"]},"fluticason":{"wirkmechanismus":"Hemmt die Entzündung direkt am Ort der Anwendung – in den Bronchien, in der Nasenschleimhaut oder in der Haut. Fluticasonpropionat ist ein stark wirksames Glukokortikoid mit sehr hoher Affinität zum Glukokortikoid-Rezeptor; es vermindert die Bildung entzündungsfördernder Botenstoffe und die Einwanderung von Entzündungszellen wie eosinophilen Granulozyten und Mastzellen. Verschluckter Wirkstoff wird in der Leber über CYP3A4 fast vollständig abgebaut (orale Bioverfügbarkeit unter 1 %), weshalb die Wirkung im ganzen Körper normalerweise gering bleibt – starke CYP3A4-Hemmer heben diesen Schutz auf.","nebenwirkungen":{"sehrHaeufig":["Pilzbefall von Mund und Rachen (Soor) bei Inhalation","Nasenbluten (Nasenspray)"],"haeufig":["Heiserkeit","Blaue Flecken (Hämatome)","Lungenentzündung (Pneumonie) bei COPD-Patienten","Nasenspray: Kopfschmerzen, unangenehmer Geschmack oder Geruch, trockene und gereizte Nase und Rachen","Creme/Salbe: Juckreiz"],"gelegentlich":["Allergische Hautreaktionen","Creme/Salbe: Brennen der Haut"],"selten":["Pilzbefall der Speiseröhre (Soor-Ösophagitis)"],"sehrSelten":["Anaphylaxie und Angioödem (schwere allergische Reaktionen)","Paradoxer Bronchospasmus (Verkrampfung der Atemwege direkt nach dem Inhalieren)","Kortison-Wirkungen im ganzen Körper: Cushing-Syndrom, Nebennierenschwäche, Wachstumsverzögerung bei Kindern, Abnahme der Knochendichte","Grauer und grüner Star (Katarakt, Glaukom)","Erhöhter Blutzucker","Angst, Schlafstörungen, Verhaltensänderungen wie Unruhe und Reizbarkeit (vor allem bei Kindern)","Durchbruch der Nasenscheidewand (Nasenspray)","Creme/Salbe: Hautverdünnung, Dehnungsstreifen, erweiterte Äderchen"],"unbekannt":["Depression, Aggressivität","Verschwommenes Sehen (Chorioretinopathie)"]},"schwangerschaft":"Nach ärztlicher Abwägung möglich. Bei Inhalation und Nasenspray gelangt nur wenig Wirkstoff in den Körper; eine gute Asthmakontrolle ist für Mutter und Kind wichtig.","stillzeit":"Der Übertritt in die Muttermilch ist beim Menschen nicht untersucht; inhalativ und nasal in üblicher Dosis nach Abwägung vertretbar, da kaum Wirkstoff ins Blut gelangt. Creme/Salbe nicht auf die Brust auftragen.","hinweise":["Nach dem Inhalieren den Mund ausspülen oder etwas essen – beugt Mundsoor und Heiserkeit vor.","Regelmässig anwenden, auch wenn keine Beschwerden bestehen; die volle Wirkung tritt erst nach einigen Tagen ein.","Nicht verwechseln mit Fluticasonfuroat (z. B. Avamys, Relvar, Trelegy) – eigener Wirkstoff mit anderer Dosierung.","Creme/Salbe dünn auftragen und im Gesicht nur kurzfristig anwenden."],"darreichung":["Dosieraerosol","Pulverinhalator (Diskus)","Nasenspray","Creme","Salbe"]},"fluticasonfuroat":{"wirkmechanismus":"Hemmt die allergische Entzündung der Schleimhaut. Fluticasonfuroat ist ein stark wirksames synthetisches Glukokortikoid, das an den Glukokortikoidrezeptor bindet und die Bildung entzündungsfördernder Botenstoffe sowie das Einwandern von Entzündungszellen unterdrückt. Verschluckter Wirkstoff wird in der Leber über CYP3A4 fast vollständig abgebaut, deshalb gelangt nur sehr wenig in den Kreislauf. Die volle Wirkung entwickelt sich über einige Tage.","nebenwirkungen":{"sehrHaeufig":["Nasenbluten (meist leicht)"],"haeufig":["Kopfschmerzen","Geschwüre der Nasenschleimhaut"],"gelegentlich":["Schmerzen, Brennen, Reizung oder Trockenheit in der Nase"],"sehrSelten":["Überempfindlichkeitsreaktionen bis Anaphylaxie, Angioödem, Hautausschlag, Nesselsucht"],"unbekannt":["Wachstumsverzögerung bei Kindern","Verschwommenes Sehen, Katarakt, Glaukom","Durchbruch der Nasenscheidewand (Septumperforation)"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; bei empfohlener Dosierung gelangt nur sehr wenig Wirkstoff in den Kreislauf.","stillzeit":"Nur nach ärztlicher Abwägung; der Übergang in die Muttermilch ist nicht untersucht.","hinweise":["Vor Gebrauch kräftig schütteln und regelmässig anwenden – die volle Wirkung tritt erst nach einigen Tagen ein.","Nach Besserung auf die niedrigste wirksame Dosis reduzieren.","Eine Ritonavir- oder Cobicistat-haltige HIV-Therapie vor Behandlungsbeginn ärztlich angeben."],"darreichung":["Nasenspray (Suspension)"]},"fluticasonfuroat-umeclidinium-vilanterol":{"wirkmechanismus":"Kombiniert Entzündungshemmung mit doppelter Bronchienerweiterung. Fluticasonfuroat ist ein stark wirksames Glukokortikoid, das in der Bronchialschleimhaut Entzündungsbotenstoffe und Entzündungszellen vermindert. Umeclidinium blockiert langanhaltend die Muskarinrezeptoren der Bronchialmuskulatur und hemmt so die Acetylcholin-Wirkung; Vilanterol stimuliert die Beta-2-Rezeptoren und entspannt die Muskulatur. Alle drei Wirkstoffe wirken etwa 24 Stunden.","nebenwirkungen":{"haeufig":["Lungenentzündung (Pneumonie)","Infekte der oberen Atemwege, Bronchitis, Rachen- und Nasennebenhöhlenentzündung, Grippe","Mundsoor (Pilzinfektion in Mund und Rachen)","Harnwegsinfekte","Kopfschmerzen","Husten, Schmerzen in Mund und Rachen","Verstopfung (Obstipation)","Gelenk- und Rückenschmerzen"],"gelegentlich":["Virale Atemwegsinfekte","Herzrhythmusstörungen: Vorhofflimmern, Herzrasen (Tachykardie)","Heiserkeit (Dysphonie)","Mundtrockenheit","Geschmacksstörungen","Knochenbrüche"],"selten":["Überempfindlichkeitsreaktionen: Anaphylaxie, Angioödem, Nesselsucht, Ausschlag","Angst, Zittern (Tremor)","Augenschmerzen, Glaukom, erhöhter Augeninnendruck","Herzklopfen","Harnverhalt, Schmerzen beim Wasserlösen","Muskelkrämpfe"],"unbekannt":["Verschwommensehen","Schwindel","Systemische Kortisonwirkungen bei Langzeitgebrauch (Nebennierenunterdrückung, Abnahme der Knochendichte, grauer Star)"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur anwenden, wenn der Nutzen für die Mutter das mögliche Risiko für das Kind klar überwiegt.","stillzeit":"Nicht bekannt, ob die Wirkstoffe in die Muttermilch übergehen; ein Risiko für den Säugling ist nicht auszuschliessen – ärztliche Abwägung.","hinweise":["Einmal täglich zur gleichen Zeit inhalieren; nicht zur Behandlung akuter Atemnot.","Nach dem Inhalieren den Mund mit Wasser ausspülen, ohne zu schlucken – beugt Mundsoor und Heiserkeit vor.","Bei Fieber, Schüttelfrost, vermehrtem oder verfärbtem Auswurf oder zunehmender Atemnot rasch ärztlich abklären (Lungenentzündung).","Bei Augenschmerzen, verschwommenem Sehen oder Problemen beim Wasserlösen ärztlich abklären lassen."],"darreichung":["Pulver zur Inhalation (Ellipta-Inhalator)"]},"folinsaeure":{"wirkmechanismus":"Liefert den Zellen eine bereits aktive Form der Folsäure, die sie für die Bildung von Erbsubstanz brauchen. Calciumfolinat ist ein Derivat der Tetrahydrofolsäure und benötigt – anders als Folsäure – keine Aktivierung durch die Dihydrofolat-Reduktase. Es umgeht daher die Blockade dieses Enzyms durch Methotrexat und schützt gesunde Zellen in Knochenmark und Schleimhäuten. Zusammen mit Fluorouracil stabilisiert es dessen Bindung an die Thymidylat-Synthase und verstärkt so die Hemmung der DNA-Synthese im Tumor.","nebenwirkungen":{"sehrHaeufig":["Mit Fluorouracil: Knochenmarkschädigung (Blutbildveränderungen, auch lebensbedrohlich)","Mit Fluorouracil: Mukositis (Entzündung der Mundschleimhaut)","Mit Fluorouracil: Durchfall, Übelkeit, Erbrechen"],"haeufig":["Mit Fluorouracil: Hand-Fuss-Syndrom (Rötung und Schmerzen an Handflächen und Fusssohlen)"],"gelegentlich":["Fieber nach der Injektion"],"selten":["Schlaflosigkeit, Unruhe, Depression nach hohen Dosen","Magen-Darm-Beschwerden nach hohen Dosen","Häufigere Anfälle bei Epilepsie"],"sehrSelten":["Allergische Reaktionen bis zur Anaphylaxie, Nesselsucht"],"unbekannt":["Mit Fluorouracil: erhöhter Ammoniakspiegel im Blut (Hyperammonämie)"]},"schwangerschaft":"Folinsäure selbst darf bei klarer Notwendigkeit angewendet werden. Methotrexat und Fluorouracil, mit denen sie kombiniert wird, dürfen in der Schwangerschaft jedoch in der Regel nicht angewendet werden.","stillzeit":"Folinsäure ist für den Säugling an sich unbedenklich; wegen der gleichzeitigen Behandlung mit Methotrexat oder Fluorouracil muss jedoch meist abgestillt werden.","hinweise":["Nach hoch dosiertem Methotrexat genau nach dem vorgegebenen Zeitplan anwenden; Methotrexat-Spiegel und Nierenwerte werden dabei kontrolliert.","Unter der Kombination mit Fluorouracil Durchfall, Fieber oder einen entzündeten Mund sofort melden (Gefahr von Austrocknung und Infektion).","Folinsäure ist nicht dasselbe wie Folsäure – Folsäure kann die Wirkung von Methotrexat nicht aufheben."],"darreichung":["Injektions- und Infusionslösung"]},"follitropin-alfa":{"wirkmechanismus":"Regt die Eierstöcke an, Eibläschen (Follikel) heranreifen zu lassen. Follitropin alfa ist gentechnisch hergestelltes menschliches follikelstimulierendes Hormon (FSH); es bindet an FSH-Rezeptoren der Granulosazellen und fördert Wachstum und Reifung der Follikel sowie die Östrogenbildung. Den Eisprung löst anschliessend eine hCG-Injektion aus. Beim Mann stimuliert FSH zusammen mit hCG die Spermienbildung in den Sertoli-Zellen des Hodens.","nebenwirkungen":{"sehrHaeufig":["Eierstockzysten","Kopfschmerzen","Reaktionen an der Einstichstelle (Schmerzen, Rötung, Bluterguss, Schwellung)"],"haeufig":["Bauchschmerzen, Blähbauch, Bauchbeschwerden","Übelkeit, Erbrechen, Durchfall","Leichtes bis mittelschweres ovarielles Überstimulationssyndrom (OHSS)","Männer: Akne, Brustvergrösserung (Gynäkomastie), Krampfader am Hoden (Varikozele), Gewichtszunahme"],"gelegentlich":["Schweres ovarielles Überstimulationssyndrom"],"selten":["Komplikationen eines schweren OHSS, z. B. Stieldrehung des Eierstocks"],"sehrSelten":["Überempfindlichkeitsreaktionen bis Anaphylaxie und Schock","Thromboembolie (meist bei schwerem OHSS)","Verschlechterung eines Asthmas"]},"schwangerschaft":"Nicht angezeigt in der Schwangerschaft.","stillzeit":"Nicht angezeigt in der Stillzeit.","hinweise":["Injektion unter die Haut nach Anleitung, möglichst täglich zur gleichen Zeit.","Regelmässige Ultraschall- und Hormonkontrollen sind nötig, um eine Überstimulation zu vermeiden.","Bei starken Bauchschmerzen, Blähbauch, Übelkeit, Atemnot oder deutlich weniger Urin sofort ärztliche Hilfe holen."],"darreichung":["Injektionslösung im Fertigpen","Pulver und Lösungsmittel zur Herstellung einer Injektionslösung"]},"follitropin-alfa-lutropin-alfa":{"wirkmechanismus":"Ersetzt die beiden Hormone der Hirnanhangsdrüse, die die Eierstöcke für die Reifung der Eibläschen (Follikel) brauchen. Follitropin alfa (FSH) fördert über FSH-Rezeptoren der Granulosazellen Wachstum und Reifung der Follikel; Lutropin alfa (LH) regt in den Thekazellen die Bildung von Androgenen an, die unter FSH-Einfluss zu Östradiol umgewandelt werden. Den Eisprung löst anschliessend eine hCG-Injektion aus.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Eierstockzysten","Reaktionen an der Einstichstelle (Schmerzen, Rötung, Bluterguss, Schwellung)"],"haeufig":["Bauchschmerzen, Blähbauch, Bauchbeschwerden","Übelkeit, Erbrechen, Durchfall","Brust- und Beckenschmerzen","Leichtes bis mittelschweres ovarielles Überstimulationssyndrom (OHSS)"],"gelegentlich":["Schweres ovarielles Überstimulationssyndrom"],"selten":["Komplikationen eines schweren OHSS, z. B. Stieldrehung des Eierstocks"],"sehrSelten":["Überempfindlichkeitsreaktionen bis Anaphylaxie und Schock","Thromboembolie (meist bei schwerem OHSS)","Verschlechterung eines Asthmas"]},"schwangerschaft":"Nicht angezeigt in der Schwangerschaft.","stillzeit":"Nicht angezeigt in der Stillzeit.","hinweise":["Injektion unter die Haut nach Anleitung, möglichst täglich zur gleichen Zeit.","Regelmässige Ultraschall- und Hormonkontrollen sind nötig, um eine Überstimulation zu vermeiden.","Bei starken Bauchschmerzen, Blähbauch, Übelkeit, Atemnot oder deutlich weniger Urin sofort ärztliche Hilfe holen."],"darreichung":["Injektionslösung im Fertigpen","Pulver und Lösungsmittel zur Herstellung einer Injektionslösung"]},"follitropin-beta":{"wirkmechanismus":"Regt die Eierstöcke an, Eibläschen (Follikel) heranreifen zu lassen. Follitropin beta ist gentechnisch hergestelltes menschliches follikelstimulierendes Hormon (FSH); es bindet an FSH-Rezeptoren der Granulosazellen und fördert Wachstum und Reifung der Follikel sowie die Östrogenbildung. Den Eisprung löst anschliessend eine hCG-Injektion aus. Beim Mann stimuliert FSH zusammen mit hCG die Spermienbildung im Hoden.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Blähbauch, Bauchschmerzen","Beckenschmerzen","Ovarielles Überstimulationssyndrom (OHSS)","Reaktionen an der Einstichstelle (Bluterguss, Schmerzen, Rötung, Schwellung, Juckreiz)","Männer: Akne, Brustvergrösserung (Gynäkomastie), Nebenhodenzyste, Hautausschlag"],"gelegentlich":["Allgemeine Überempfindlichkeitsreaktionen (Rötung, Nesselsucht, Ausschlag, Juckreiz)","Übelkeit, Verstopfung, Durchfall, Bauchbeschwerden","Brustbeschwerden, Zwischenblutungen","Eierstockzysten, Vergrösserung von Eierstöcken oder Gebärmutter","Stieldrehung eines Eierstocks (Ovarialtorsion)"],"selten":["Thromboembolie"]},"schwangerschaft":"Nicht angezeigt in der Schwangerschaft.","stillzeit":"Nicht angezeigt in der Stillzeit.","hinweise":["Injektion unter die Haut nach Anleitung, möglichst täglich zur gleichen Zeit.","Regelmässige Ultraschall- und Hormonkontrollen sind nötig, um eine Überstimulation zu vermeiden.","Bei starken Bauchschmerzen, Blähbauch, Übelkeit, Atemnot oder deutlich weniger Urin sofort ärztliche Hilfe holen."],"darreichung":["Injektionslösung (Patrone für Pen)"]},"follitropin-delta":{"wirkmechanismus":"Regt die Eierstöcke an, mehrere Eibläschen (Follikel) heranreifen zu lassen. Follitropin delta ist menschliches follikelstimulierendes Hormon (FSH), das in einer menschlichen Zelllinie hergestellt wird. Es bindet an FSH-Rezeptoren der Granulosazellen und fördert Wachstum und Reifung der Follikel. Die Tagesdosis wird aus dem Anti-Müller-Hormon (AMH) im Blut und dem Körpergewicht berechnet, um eine Über- oder Unterstimulation zu vermeiden.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Beckenschmerzen und -beschwerden, Schmerzen im Bereich der Eierstöcke","Übelkeit","Müdigkeit","Ovarielles Überstimulationssyndrom (OHSS)"],"gelegentlich":["Stimmungsschwankungen","Schläfrigkeit, Schwindel","Durchfall, Erbrechen, Verstopfung, Bauchbeschwerden","Vaginale Blutungen","Brustbeschwerden (Schmerzen, Spannen)"],"unbekannt":["Überempfindlichkeitsreaktionen","Thromboembolie","Stieldrehung eines Eierstocks (Ovarialtorsion)"]},"schwangerschaft":"Nicht angezeigt in der Schwangerschaft.","stillzeit":"Nicht angezeigt in der Stillzeit.","hinweise":["Vor dem ersten Zyklus wird der AMH-Wert im Blut bestimmt; die Dosis gilt für den ganzen Zyklus.","Regelmässige Ultraschall- und Hormonkontrollen sind nötig, um eine Überstimulation zu vermeiden.","Bei starken Bauchschmerzen, Blähbauch, Übelkeit, Atemnot oder deutlich weniger Urin sofort ärztliche Hilfe holen."],"darreichung":["Injektionslösung im Fertigpen"]},"folsaeure":{"wirkmechanismus":"Ersetzt Folsäure, die für die Zellteilung und Blutbildung nötig ist. Folsäure wird im Körper über das Enzym Dihydrofolat-Reduktase zur aktiven Tetrahydrofolsäure umgewandelt. Diese überträgt Kohlenstoff-Bausteine für die Herstellung von Purinen und Thymidin, also für die DNA-Synthese – besonders wichtig in sich rasch teilenden Geweben wie Knochenmark und dem sich entwickelnden Nervensystem des Embryos. Zusammen mit Vitamin B12 wird zudem Homocystein zu Methionin umgebaut.","nebenwirkungen":{"selten":["Magen-Darm-Beschwerden wie Übelkeit, Blähungen (bei hohen Dosen)","Schlafstörungen, Unruhe, depressive Verstimmung (bei hohen Dosen)"],"sehrSelten":["Überempfindlichkeitsreaktionen (Hautrötung, Juckreiz)","Bronchospasmus (Verkrampfung der Atemwege)","Anaphylaktischer Schock (schwere allergische Reaktion)"]},"schwangerschaft":"Erlaubt und empfohlen: 0,4 mg täglich ab mindestens 4 Wochen vor der Empfängnis bis Ende des 1. Schwangerschaftsdrittels; bei erhöhtem Risiko für Neuralrohrdefekte auf ärztliche Verordnung höher dosiert.","stillzeit":"Erlaubt; Folsäure geht in die Muttermilch über, der Bedarf ist in der Stillzeit erhöht.","hinweise":["Bei Kinderwunsch rechtzeitig beginnen: das Neuralrohr schliesst sich bereits in den ersten 4 Wochen der Schwangerschaft.","Hoch dosierte Folsäure (5 mg) nur auf ärztliche Verordnung; vorher einen Vitamin-B12-Mangel ausschliessen lassen.","Während einer Chemotherapie keine folsäurehaltigen Präparate ohne Rücksprache einnehmen."],"darreichung":["Tabletten (0,4 mg und 5 mg)","Kombinationspräparate mit Eisen oder Multivitaminen"]},"fondaparinux":{"wirkmechanismus":"Hemmt die Blutgerinnung und verhindert so Blutgerinnsel. Fondaparinux ist ein vollsynthetisches Pentasaccharid, das genau der Bindungsstelle des Heparins für Antithrombin entspricht. Es bindet selektiv an Antithrombin und verstärkt dessen Hemmung des Gerinnungsfaktors Xa etwa 300-fach; Thrombin selbst wird nicht gehemmt. Weil es nicht mit dem Plättchenfaktor 4 reagiert, ist eine heparininduzierte Thrombozytopenie praktisch nicht zu erwarten. Fondaparinux wird unverändert über die Nieren ausgeschieden und hat eine lange Halbwertszeit (etwa 17–21 Stunden), sodass eine Spritze pro Tag genügt.","nebenwirkungen":{"haeufig":["Blutungen (nach Operationen, Blutergüsse, Nasenbluten, Magen-Darm-, Harnwegs- und Scheidenblutungen)","Anämie (Blutarmut)"],"gelegentlich":["Thrombozytopenie oder Thrombozytose (veränderte Plättchenzahl), Purpura (punktförmige Hautblutungen)","Übelkeit, Erbrechen","Erhöhte Leberwerte, Leberfunktionsstörung","Hautausschlag, Juckreiz","Wassereinlagerungen, Fieber, Wundsekret"],"selten":["Hirnblutung und Blutungen im hinteren Bauchraum (retroperitoneal)","Allergische Reaktionen","Hypokaliämie (Kaliummangel)","Schwindel, Kopfschmerzen, Benommenheit, Angst, Verwirrtheit","Blutdruckabfall, Atemnot, Husten","Bauchschmerzen, Verdauungsbeschwerden, Verstopfung, Durchfall","Reaktionen an der Einstichstelle"],"sehrSelten":["Angioödem, anaphylaktische oder anaphylaktoide Reaktionen"]},"schwangerschaft":"Keine ausreichenden Erfahrungen beim Menschen; nur anwenden, wenn eindeutig erforderlich.","stillzeit":"Im Tierversuch Übergang in die Milch; Stillen während der Behandlung wird nicht empfohlen.","hinweise":["Unter die Haut spritzen (Bauch, abwechselnd links und rechts), nie in den Muskel; die Luftblase in der Fertigspritze nicht entfernen.","Vor Operationen, Zahnbehandlungen und Spinal- oder Periduralanästhesie die Behandlung angeben.","Nierenfunktion kontrollieren lassen, besonders bei älteren Menschen.","Bei Blutungszeichen (schwarzer Stuhl, Blut im Urin, ungewöhnliche Blutergüsse) sofort ärztlichen Rat holen."],"darreichung":["Injektionslösung in Fertigspritzen"]},"formoterol":{"wirkmechanismus":"Erweitert die Bronchien innert 1–3 Minuten und hält sie etwa 12 Stunden offen. Formoterol stimuliert selektiv Beta-2-Rezeptoren der Bronchialmuskulatur; über einen Anstieg von cAMP erschlafft die glatte Muskulatur. Dank des raschen Wirkungseintritts wird es in Kombination mit Budesonid oder Beclometason auch als Bedarfsmedikament eingesetzt. Gegen die Entzündung der Atemwege wirkt es nicht.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Zittern (Tremor)","Herzklopfen"],"gelegentlich":["Unruhe, Nervosität, Schlafstörungen","Schwindel","Beschleunigter Puls (Tachykardie)","Muskelkrämpfe"],"selten":["Überempfindlichkeitsreaktionen (Ausschlag, Nesselsucht, Juckreiz)","Hypokaliämie (Kaliummangel)","Herzrhythmusstörungen (Vorhofflimmern, supraventrikuläre Tachykardie, Extrasystolen)","Bronchospasmus, auch paradox nach der Inhalation"],"sehrSelten":["Hyperglykämie (erhöhter Blutzucker)","Geschmacksstörungen","Angina pectoris, QT-Verlängerung","Blutdruckschwankungen"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; ein gut kontrolliertes Asthma ist für Mutter und Kind wichtig.","stillzeit":"Nur nach ärztlicher Abwägung; ob Formoterol in die Muttermilch übergeht, ist nicht bekannt.","hinweise":["Bei Asthma immer zusammen mit einem inhalativen Kortison anwenden, am einfachsten als Kombinationspräparat.","Inhalationstechnik in der Apotheke oder Praxis zeigen lassen; Kapseln nur in den Inhalator einlegen, nie schlucken.","Bei zunehmendem Bedarf oder nachlassender Wirkung ärztlich abklären lassen."],"darreichung":["Pulverinhalator","Kapseln zur Inhalation"]},"formoterol-beclometason":{"wirkmechanismus":"Verbindet eine entzündungshemmende mit einer rasch einsetzenden, lang anhaltenden bronchienerweiternden Wirkung. Beclometasondipropionat ist ein Prodrug: In der Lunge entsteht daraus das wirksame Beclometason-17-monopropionat, das die Entzündung der Bronchialschleimhaut dämpft. Formoterol stimuliert Beta-2-Rezeptoren und weitet die Bronchien innert Minuten für etwa 12 Stunden. Dank sehr feiner Partikel erreicht der Wirkstoff auch die kleinen Atemwege, weshalb die Kortisondosis tiefer ist als bei herkömmlichen Beclometason-Präparaten.","nebenwirkungen":{"haeufig":["Pilzinfektion in Mund und Rachen (Soor), Rachenentzündung","Kopfschmerzen","Heiserkeit (Dysphonie)","Lungenentzündung (bei COPD)"],"gelegentlich":["Grippe, Nebenhöhlenentzündung, Schnupfen","Zittern, Schwindel, Unruhe","Herzklopfen, beschleunigter Puls, Vorhofflimmern, QT-Verlängerung","Husten, Rachenreizung, Asthmaanfall","Übelkeit, Mundtrockenheit, Geschmacksstörungen","Hypokaliämie, Hyperglykämie","Hautausschlag, Juckreiz, Nesselsucht","Muskelkrämpfe, Muskelschmerzen"],"selten":["Paradoxer Bronchospasmus","Angioödem","Ventrikuläre Extrasystolen, Angina pectoris","Blutdruckanstieg oder -abfall"],"sehrSelten":["Unterdrückung der Nebennierenfunktion, Wachstumsverzögerung bei Kindern, verminderte Knochendichte","Glaukom, Katarakt","Thrombozytopenie (Mangel an Blutplättchen)","Periphere Ödeme (Wassereinlagerungen)"],"unbekannt":["Schlafstörungen, Angst, Depression, Aggressivität, Verhaltensänderungen","Verschwommenes Sehen"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; ein gut kontrolliertes Asthma ist für Mutter und Kind wichtig. Gegen Ende der Schwangerschaft zurückhaltend, da Beta-2-Sympathomimetika die Wehen hemmen können.","stillzeit":"Nur nach ärztlicher Abwägung.","hinweise":["Nach jeder Inhalation den Mund mit Wasser ausspülen und ausspucken – das beugt Soor und Heiserkeit vor.","Regelmässig anwenden, auch ohne Beschwerden; nicht abrupt absetzen.","Inhalationstechnik in der Apotheke oder Praxis zeigen lassen; beim Dosieraerosol kann eine Inhalierhilfe (Spacer) sinnvoll sein."],"darreichung":["Dosieraerosol","Pulverinhalator"]},"formoterol-budesonid":{"wirkmechanismus":"Verbindet eine entzündungshemmende mit einer rasch einsetzenden, lang anhaltenden bronchienerweiternden Wirkung. Budesonid ist ein Glukokortikoid, das die Entzündung der Bronchialschleimhaut und die Überempfindlichkeit der Atemwege dämpft. Formoterol stimuliert Beta-2-Rezeptoren der Bronchialmuskulatur; die Bronchien weiten sich innert 1–3 Minuten für etwa 12 Stunden. Wegen des raschen Wirkungseintritts kann die Kombination bei Asthma gleichzeitig zur Dauer- und Bedarfsbehandlung dienen.","nebenwirkungen":{"haeufig":["Pilzinfektion in Mund und Rachen (Soor)","Lungenentzündung (bei COPD)","Kopfschmerzen","Zittern (Tremor)","Herzklopfen","Leichte Rachenreizung, Husten, Heiserkeit"],"gelegentlich":["Angst, Unruhe, Nervosität, Schlafstörungen","Schwindel","Übelkeit","Beschleunigter Puls (Tachykardie)","Verschwommenes Sehen","Muskelkrämpfe","Blutergüsse"],"selten":["Überempfindlichkeitsreaktionen (Ausschlag, Nesselsucht, Juckreiz, Angioödem, Anaphylaxie)","Hypokaliämie (Kaliummangel)","Herzrhythmusstörungen (Vorhofflimmern, supraventrikuläre Tachykardie, Extrasystolen)","Bronchospasmus (Verkrampfung der Atemwege)"],"sehrSelten":["Cushing-Syndrom, Unterdrückung der Nebennierenfunktion, Wachstumsverzögerung, verminderte Knochendichte","Hyperglykämie (erhöhter Blutzucker)","Depression, Verhaltensänderungen","Katarakt, Glaukom","Angina pectoris, QT-Verlängerung","Geschmacksstörungen","Blutdruckschwankungen"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; ein gut kontrolliertes Asthma ist für Mutter und Kind wichtig. Für inhaliertes Budesonid liegen umfangreiche Erfahrungen ohne Hinweis auf Fehlbildungen vor.","stillzeit":"Budesonid geht in geringen Mengen in die Muttermilch über; ob Formoterol übergeht, ist nicht bekannt. Anwendung nach ärztlicher Abwägung.","hinweise":["Nach jeder Inhalation den Mund mit Wasser ausspülen und ausspucken – das beugt Soor und Heiserkeit vor.","Wer das Präparat auch bei Bedarf anwendet: Wird es an mehreren Tagen deutlich häufiger als gewohnt gebraucht, ärztlich abklären lassen.","Nicht abrupt absetzen; eine Ritonavir- oder Cobicistat-haltige HIV-Therapie ärztlich angeben."],"darreichung":["Pulverinhalator","Dosieraerosol"]},"formoterol-fluticason":{"wirkmechanismus":"Wirkt bei Asthma auf zwei Wegen: Es dämpft die Entzündung der Bronchien und erweitert sie. Fluticasonpropionat ist ein stark wirksames Glukokortikoid, das über den Glukokortikoid-Rezeptor die Bildung von Entzündungsbotenstoffen und die Einwanderung von Entzündungszellen in die Bronchialschleimhaut hemmt. Formoterol stimuliert selektiv die Beta-2-Rezeptoren der Bronchialmuskulatur und entspannt sie; die Wirkung setzt innerhalb weniger Minuten ein und hält etwa 12 Stunden an.","nebenwirkungen":{"gelegentlich":["Mundsoor (Pilzinfektion in Mund und Rachen)","Kopfschmerzen, Schwindel","Zittern (Tremor)","Herzklopfen, Extraschläge des Herzens (ventrikuläre Extrasystolen)","Heiserkeit (Dysphonie), Rachenreizung","Verschlechterung des Asthmas","Schlafstörungen"],"selten":["Hyperglykämie (erhöhter Blutzucker)","Angina pectoris (Brustenge), Herzrasen (Tachykardie)","Bluthochdruck","Atemnot, Husten","Mundtrockenheit, Durchfall, Verdauungsbeschwerden","Hautausschlag, Juckreiz","Muskelkrämpfe, Geschmacksstörungen","Ungewöhnliche Träume, Unruhe"],"unbekannt":["Paradoxer Bronchospasmus (Verkrampfung der Atemwege direkt nach dem Inhalieren)","Hypokaliämie (Kaliummangel)","Systemische Kortisonwirkungen bei hoher Dosis über lange Zeit (Nebennierenunterdrückung, Wachstumsverzögerung, Abnahme der Knochendichte, grauer und grüner Star)","Verschwommensehen","Psychomotorische Überaktivität, Angst, Depression, Aggressivität (v. a. bei Kindern)"]},"schwangerschaft":"Nur anwenden, wenn der Nutzen für die Mutter das mögliche Risiko für das Kind überwiegt; eine gute Asthmakontrolle ist auch für das Ungeborene wichtig. Formoterol kann kurz vor der Geburt die Wehen hemmen.","stillzeit":"Nicht bekannt, ob die Wirkstoffe in die Muttermilch übergehen; Anwendung nur nach ärztlicher Nutzen-Risiko-Abwägung.","hinweise":["Regelmässig wie verordnet anwenden (in der Regel morgens und abends), auch bei Beschwerdefreiheit; für akute Atemnot immer ein separates Notfallspray bereithalten.","Nach jeder Anwendung den Mund mit Wasser ausspülen und ausspucken – beugt Mundsoor und Heiserkeit vor.","Nicht abrupt absetzen; bei Verschlechterung oder häufigerem Gebrauch des Notfallsprays ärztlich melden.","Inhalationstechnik regelmässig in Apotheke oder Praxis überprüfen lassen; bei Koordinationsproblemen eine Inhalierhilfe (Spacer) verwenden."],"darreichung":["Dosieraerosol (Inhalationsspray)"]},"fosfomycin":{"wirkmechanismus":"Hindert Bakterien daran, ihre Zellwand aufzubauen, und tötet sie dadurch ab. Fosfomycin hemmt irreversibel das Enzym MurA (UDP-N-Acetylglucosamin-Enolpyruvyl-Transferase) und blockiert damit den allerersten Schritt der Peptidoglykan-Synthese – früher als Penicilline oder Cephalosporine, weshalb kaum Kreuzresistenzen bestehen. Der Wirkstoff wird unverändert über die Niere ausgeschieden und erreicht nach einer einzigen Dosis für 1–2 Tage hohe Konzentrationen im Urin.","nebenwirkungen":{"haeufig":["Durchfall","Übelkeit","Dyspepsie (Verdauungsbeschwerden)","Bauchschmerzen","Kopfschmerzen","Schwindel","Vulvovaginitis (Scheidenentzündung, z. B. Scheidenpilz)"],"gelegentlich":["Erbrechen","Hautausschlag, Juckreiz, Nesselsucht","Parästhesien (Kribbeln)"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion) bis Schock","Angioödem (Schwellung von Gesicht, Lippen, Rachen)","Antibiotika-assoziierte Kolitis (Clostridioides difficile)"]},"schwangerschaft":"Erfahrungen mit der Einmalgabe zeigen kein erhöhtes Risiko für das Kind; Anwendung nach ärztlicher Abwägung möglich.","stillzeit":"Geht in geringen Mengen in die Muttermilch über. Eine einmalige Dosis ist nach ärztlicher Abwägung vertretbar.","hinweise":["Granulat in einem Glas Wasser auflösen und sofort trinken – auf nüchternen Magen, am besten am Abend vor dem Schlafengehen nach Entleeren der Blase.","Die Beschwerden klingen oft erst nach 2–3 Tagen ab; bei Fieber, Rückenschmerzen oder fehlender Besserung ärztlich abklären lassen.","Nach der Einnahme ausreichend trinken."],"darreichung":["Granulat zur Herstellung einer Trinklösung (Beutel)"]},"fremanezumab":{"wirkmechanismus":"Beugt Migräneanfällen vor, indem es einen Botenstoff abfängt, der bei der Migräne Gefässerweiterung und Schmerz vermittelt. Fremanezumab ist ein humanisierter IgG2-Antikörper, der den Botenstoff CGRP (Calcitonin Gene-Related Peptide) selbst bindet und so dessen Andocken an den Rezeptor verhindert. Als Eiweiss wird es nicht über Leberenzyme (CYP) abgebaut; dank langer Halbwertszeit genügt eine Injektion pro Monat oder eine dreifache Dosis alle 3 Monate.","nebenwirkungen":{"sehrHaeufig":["Schmerzen an der Injektionsstelle","Verhärtung an der Injektionsstelle","Rötung an der Injektionsstelle"],"haeufig":["Juckreiz an der Injektionsstelle"],"gelegentlich":["Ausschlag an der Injektionsstelle","Überempfindlichkeitsreaktionen (Ausschlag, Juckreiz, Nesselsucht, Schwellungen)"],"selten":["Anaphylaxie (schwere allergische Reaktion)"]},"schwangerschaft":"Nur begrenzte Erfahrungen; aus Vorsicht während der Schwangerschaft nicht anwenden.","stillzeit":"Unbekannt, ob Fremanezumab in die Muttermilch übergeht; besonders in den ersten Tagen nach der Geburt möglich – nur nach ärztlicher Abwägung.","hinweise":["Fertigspritze oder Fertigpen vor der Injektion etwa 30 Minuten bei Raumtemperatur liegen lassen; im Kühlschrank lagern, nicht einfrieren.","Die Wirkung wird nach etwa 3 Monaten ärztlich beurteilt; Akutmittel gegen Migräneanfälle weiter wie verordnet verwenden.","Bei Atemnot, Schwellungen im Gesicht oder starkem Ausschlag sofort ärztliche Hilfe holen."],"darreichung":["Injektionslösung in Fertigspritze oder Fertigpen (subkutan)"]},"fsme-impfstoff":{"wirkmechanismus":"Regt das Immunsystem an, eigene Abwehrstoffe gegen das FSME-Virus zu bilden. Der Impfstoff enthält mit Formaldehyd abgetötete FSME-Viren (FSME-Immun: Stamm Neudörfl, Encepur: Stamm K23), die an Aluminiumhydroxid gebunden sind und so eine stärkere Immunantwort auslösen. Es entstehen neutralisierende Antikörper, die das Virus nach einem Zeckenstich unschädlich machen. Ein langdauernder Schutz erfordert eine Grundimmunisierung mit 3 Dosen und Auffrischimpfungen.","nebenwirkungen":{"sehrHaeufig":["Schmerzen an der Einstichstelle","Kopfschmerzen","Muskelschmerzen","Unwohlsein, Müdigkeit"],"haeufig":["Übelkeit","Gelenkschmerzen","Fieber (vor allem bei Kleinkindern nach der ersten Dosis)","Rötung und Schwellung an der Einstichstelle","Grippeähnliche Beschwerden"],"gelegentlich":["Lymphknotenschwellung","Erbrechen"],"selten":["Überempfindlichkeitsreaktionen","Schwindel","Durchfall, Bauchschmerzen"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Krampfanfälle, auch Fieberkrämpfe","Nervenentzündungen wie Guillain-Barré-Syndrom","Hirnhautreizung (Meningismus)","Verschlechterung von Autoimmunerkrankungen (z. B. multiple Sklerose)"]},"schwangerschaft":"Keine ausreichenden Daten. Impfung nur bei dringendem Ansteckungsrisiko nach ärztlicher Nutzen-Risiko-Abwägung.","stillzeit":"Nicht bekannt, ob Impfstoffbestandteile in die Muttermilch übergehen. Impfung bei Ansteckungsrisiko nach ärztlicher Abwägung möglich.","hinweise":["Grundimmunisierung mit 3 Dosen; in der Schweiz wird eine Auffrischimpfung alle 10 Jahre empfohlen.","Am besten in der kalten Jahreszeit beginnen, damit der Schutz zu Beginn der Zeckensaison besteht; ein Schnellschema ist möglich.","Die Impfung schützt nicht vor Borreliose – Zeckenschutz und Absuchen nach Zecken bleiben wichtig."],"darreichung":["Injektionssuspension in Fertigspritze"]},"fulvestrant":{"wirkmechanismus":"Blockiert den Östrogenrezeptor in Brustkrebszellen und sorgt dafür, dass er abgebaut wird. Fulvestrant bindet kompetitiv und mit hoher Affinität an den Östrogenrezeptor, verhindert dessen Aktivierung und beschleunigt seinen Abbau (Downregulation). Anders als Tamoxifen hat es keine östrogenartige Teilwirkung.","nebenwirkungen":{"sehrHaeufig":["Reaktionen an der Injektionsstelle (Schmerzen, Entzündung)","Schwäche, Müdigkeit","Übelkeit","Erhöhte Leberwerte","Hitzewallungen","Gelenk- und Muskelschmerzen","Hautausschlag"],"haeufig":["Kopfschmerzen","Venöse Thromboembolien","Harnwegsinfektionen","Erbrechen, Durchfall, Appetitlosigkeit","Erhöhtes Bilirubin","Rückenschmerzen","Ischiasschmerzen, Nervenschmerzen an der Injektionsstelle","Überempfindlichkeitsreaktionen, Scheidenblutungen"],"gelegentlich":["Leberversagen, Hepatitis","Blutungen und Blutergüsse an der Injektionsstelle","Scheidenpilz, Ausfluss"]},"schwangerschaft":"Kontraindiziert. Frauen im gebärfähigen Alter sollen während und bis 2 Jahre nach der letzten Dosis sicher verhüten.","stillzeit":"Kontraindiziert.","hinweise":["Wird als zwei Spritzen in die Gesässmuskulatur gegeben, anfangs zusätzlich nach 2 Wochen, dann monatlich.","Fulvestrant kann bestimmte Östradiol-Labortests verfälschen – bei Blutentnahmen angeben.","Schmerzen, die vom Gesäss ins Bein ausstrahlen, melden."],"darreichung":["Injektionslösung in Fertigspritze (in den Muskel)"]},"furosemid":{"wirkmechanismus":"Bewirkt eine rasche und kräftige Ausscheidung von Salz und Wasser über die Niere. Furosemid hemmt den Natrium-Kalium-2-Chlorid-Cotransporter (NKCC2) im aufsteigenden Teil der Henle-Schleife, wo ein grosser Teil des Natriums zurückgewonnen wird; dadurch steigt die Ausscheidung von Natrium, Chlorid und Wasser, aber auch von Kalium, Calcium und Magnesium deutlich an. Nach Einnahme setzt die Wirkung innerhalb einer Stunde ein und hält 4–6 Stunden an, nach intravenöser Gabe beginnt sie innerhalb weniger Minuten. Bei akuter Herzinsuffizienz entlastet es das Herz zusätzlich durch eine Erweiterung der Venen. Die Wirkung bleibt auch bei eingeschränkter Nierenfunktion erhalten.","nebenwirkungen":{"sehrHaeufig":["Elektrolytstörungen","Flüssigkeitsmangel (Dehydratation, Hypovolämie), besonders bei älteren Menschen","Anstieg von Kreatinin und Triglyceriden im Blut"],"haeufig":["Hypokaliämie, Hyponatriämie, Hypochlorämie (Kalium-, Natrium-, Chloridmangel)","Bluteindickung (Hämokonzentration)","Erhöhtes Cholesterin, erhöhte Harnsäure, Gichtanfälle","Hepatische Enzephalopathie bei Leberinsuffizienz","Vermehrte Harnmenge"],"gelegentlich":["Thrombozytopenie (Mangel an Blutplättchen)","Hörstörungen, meist vorübergehend, selten Taubheit","Übelkeit","Juckreiz, Nesselsucht, Hautausschläge, bullöse Hautreaktionen, Photosensibilität","Verschlechterung der Blutzuckereinstellung"],"selten":["Anaphylaktische Reaktionen","Tinnitus (Ohrgeräusche)","Interstitielle Nephritis (Nierenentzündung)","Vaskulitis (Gefässentzündung)","Eosinophilie, Leukopenie","Erbrechen, Durchfall","Kribbeln (Parästhesien), Fieber"],"sehrSelten":["Agranulozytose, aplastische und hämolytische Anämie","Akute Pankreatitis (Bauchspeicheldrüsenentzündung)","Gallenstau in der Leber, Anstieg der Leberwerte"],"unbekannt":["Hypokalzämie, Hypomagnesiämie, metabolische Alkalose","Schwindel, Ohnmacht, Kopfschmerzen","Thrombosen","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS, AGEP)","Akutes Nierenversagen, Harnverhalt","Nierenverkalkung und offener Ductus arteriosus bei Frühgeborenen","Rhabdomyolyse (Muskelzerfall)"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit und kurzzeitig: Furosemid gelangt zum Kind und kann dessen Elektrolythaushalt sowie die Durchblutung der Plazenta beeinträchtigen; das Wachstum des Kindes überwachen.","stillzeit":"Kontraindiziert: Furosemid geht in die Muttermilch über und kann die Milchbildung hemmen; ist eine Behandlung nötig, abstillen.","hinweise":["Am Morgen bzw. bei zweimaliger Gabe spätestens am frühen Nachmittag einnehmen, um nächtlichen Harndrang zu vermeiden.","Körpergewicht bei Ödemen täglich kontrollieren; bei Durchfall, Erbrechen, starkem Schwitzen oder Schwindel ärztlichen Rat einholen (Austrocknung, Elektrolytverlust).","Kalium, Natrium, Nierenwerte, Blutzucker und Harnsäure regelmässig kontrollieren lassen.","Kann die Fahrtüchtigkeit beeinträchtigen, besonders zu Behandlungsbeginn und zusammen mit Alkohol."],"darreichung":["Tabletten","Retardkapseln","Injektionslösung","Infusionskonzentrat"]},"fusidinsaeure":{"wirkmechanismus":"Hemmt das Wachstum von Bakterien, indem es ihre Eiweissherstellung blockiert. Fusidinsäure hat eine steroidähnliche Struktur, wirkt aber nicht wie Kortison: Sie hält den Elongationsfaktor G (EF-G) am bakteriellen Ribosom fest und verhindert so, dass die Eiweisskette verlängert wird. Sie wirkt vor allem gegen Staphylokokken, auch gegen viele Methicillin-resistente Stämme, und dringt gut in Haut und Gewebe ein. Weil sich rasch Resistenzen bilden, soll die Behandlung kurz sein.","nebenwirkungen":{"haeufig":["Magen-Darm-Beschwerden wie Übelkeit, Erbrechen, Durchfall, Bauchschmerzen, Verdauungsbeschwerden (Tabletten)","Brennen, Juckreiz oder Schmerzen am Auge, kurzzeitig verschwommenes Sehen (Augentropfen)"],"gelegentlich":["Brennen, Reizung oder Schmerzen an der Auftragsstelle (Creme, Salbe)","Kontaktekzem, Ausschlag, Juckreiz, Rötung","Kopfschmerzen, Schwindel, Müdigkeit (Tabletten)","Lidschwellung, vermehrter Tränenfluss (Augentropfen)"],"selten":["Angioödem (Schwellung von Haut und Schleimhäuten), Nesselsucht, Blasenbildung","Bindehautentzündung (Creme oder Salbe im Augenbereich)"],"unbekannt":["Gelbsucht und Leberfunktionsstörungen (Tabletten)","Blutbildveränderungen bis Agranulozytose oder Panzytopenie (Tabletten, vor allem bei längerer Einnahme)","Rhabdomyolyse (Muskelzerfall), vor allem zusammen mit Statinen","Schwere allergische Reaktionen (Anaphylaxie)"]},"schwangerschaft":"Creme, Salbe und Augentropfen können angewendet werden, da kaum Wirkstoff in den Körper gelangt. Tabletten nur nach strenger ärztlicher Abwägung, besonders gegen Ende der Schwangerschaft (theoretisches Gelbsucht-Risiko beim Neugeborenen).","stillzeit":"Äusserliche Anwendung und Augentropfen möglich, aber nicht auf die Brust auftragen. Tabletten: Fusidinsäure geht in die Muttermilch über – nur nach ärztlicher Abwägung.","hinweise":["Wer ein Statin (Cholesterinsenker) einnimmt, muss dies vor einer Behandlung mit Fusidinsäure-Tabletten unbedingt angeben.","Creme und Salbe nach dem Auftragen von den Händen waschen und nicht länger als ärztlich verordnet anwenden.","Augentropfen: während einer Bindehautentzündung keine Kontaktlinsen tragen; nach dem Eintropfen erst Auto fahren, wenn die Sicht klar ist.","Fucicort und Fucidin-H enthalten zusätzlich Kortison: nicht ohne ärztliche Anweisung im Gesicht oder grossflächig anwenden."],"darreichung":["Creme","Salbe","Augentropfen (zähflüssig)","Filmtabletten"]}});
